import { operatorLesson } from './operator-lesson.js';
import { advancedManifests as files, advancedAssets } from './advanced-manifests.js';
const k = 'kubectl --context kubelab -n kubelab';
const cluster = 'kubectl --context kubelab';
const S = (title, command, why, parts, expected, problem = '', exitCode = 0) => ({ title, command, why, parts, expected, problem, exitCode });
const R = (title, paragraphs, code = '', fields = []) => ({ title, paragraphs, code, fields });
const L = value => ({ minutes: 45, context: 'kubelab', namespace: 'kubelab', before: 'Сначала выполните начальные одиннадцать уроков, затем двигайтесь по порядку этого модуля. Нужны работающий профиль kubelab и образ kubelab:1.0. Дополнительные требования указаны в тексте занятия.', ...value, examples: [...(value.files || []).map(name => ({ path: `k8s/advanced/${name}.yaml`, text: files[name].text })), ...(value.assetPaths || []).map(path => ({ path, text: advancedAssets[path] }))] });
const apply = (name, why, expected) => S('Примените учебный файл', `${cluster} apply -f k8s/advanced/${name}.yaml`, why, [['apply -f', 'Создать или обновить объекты из указанного полного файла. Путь считается от рабочей папки.']], expected);
const remove = (name, why) => S('Завершите опыт', `${cluster} delete -f k8s/advanced/${name}.yaml`, why, [['delete -f', 'Удалить перечисленные в этом файле объекты, а не весь кластер.']], 'Названные учебные объекты удалены.');
export const advancedLessons = [
  L({ id: 'architecture', module: 'Устройство и управление', title: "Управляющие компоненты Kubernetes", tag: 'Управляющие компоненты',
    goal: 'Связать сервер управления, хранилище, контроллеры, планировщик и службу узла в одну понятную последовательность.',
    introduction: ["Команда kubectl apply передаёт описание объекта серверу API. Она не запускает контейнер непосредственно. После проверки и сохранения запроса в работу вступают контроллеры, планировщик и компоненты узла. Разделение этих обязанностей позволяет управлять множеством приложений через общий API.","Проследим эту последовательность на примере Deployment. Контроллер создаёт ReplicaSet, затем появляются Pod, планировщик выбирает узлы, а kubelet организует запуск контейнеров. Одновременно рассмотрим etcd, где хранится состояние управляющей системы. Понимание этой последовательности понадобится при диагностике случая, когда описание принято, но приложение ещё не работает."],
    terms: [['Сервер управления (kube-apiserver)', 'Точка входа для запросов к объектам Kubernetes.'], ['etcd', 'Хранилище состояния управляющей системы. Это не база данных вашего приложения.'], ['Контроллер', 'Программа, сравнивающая желаемое состояние с фактическим и выполняющая необходимые действия.'], ['Планировщик', 'Выбирает подходящий узел для Pod, которому узел ещё не назначен.']],
    sections: [R("От API к работающему процессу", ['Сервер управления принимает описание Deployment. Контроллер Deployment создаёт ReplicaSet, а контроллер ReplicaSet создаёт Pod. Планировщик записывает выбранный узел. kubelet этого узла замечает назначенный Pod и через среду выполнения организует запуск контейнера. Проверки готовности затем определяют, можно ли направлять ему запросы.', 'etcd сохраняет объекты и их состояние. Содержимое томов приложения туда автоматически не попадает. Резервная копия etcd и резервная копия базы данных решают разные задачи. Контроллеры могут временно отставать, поэтому цепочка не обязана завершиться за время одного запроса apply.']), R("Отказы управляющих компонентов", ['Если недоступен сервер управления, новые команды kubectl могут не проходить, но уже работающие контейнеры не обязаны немедленно остановиться. Если недоступен узел, его контейнеры нельзя считать доступными даже при сохранённом Deployment. Если контроллер остановлен, сохранённое желаемое состояние может некоторое время не исполняться.', 'В Minikube управляющие компоненты и приложения делят один узел. Вывод get pods из kube-system помогает увидеть состав этого окружения, но не доказывает отказоустойчивость. Не удаляйте управляющие Pod ради опыта: для такого испытания нужен отдельный подготовленный стенд и план восстановления.'])],
    steps: [S('Посмотрите управляющие Pod', `${cluster} -n kube-system get pods`, 'Найдите имена с kube-apiserver, kube-controller-manager, kube-scheduler и etcd. В других способах установки компоненты могут быть организованы иначе.', [['-n kube-system', 'Пространство системных компонентов, не наших приложений.']], 'В обычном Minikube видны работающие управляющие Pod и сетевые службы.'), S('Проверьте готовность сервера управления', `${cluster} get --raw=/readyz`, 'Запрашиваем служебный адрес самого интерфейса Kubernetes. Это не /readyz нашего веб-сервера.', [['--raw=/readyz', 'Выполнить запрос к указанному пути сервера Kubernetes.']], 'Ответ ok и код 0. Это проверка готовности сервера, а не всех приложений.'), S('Найдите связанное ReplicaSet', `${k} get replicasets`, 'Увидьте промежуточный объект между Deployment и Pod. После обновлений старых ReplicaSet может быть несколько.', [['get replicasets', 'Получить наборы реплик в учебном пространстве имён.']], 'У текущего набора есть желаемые и готовые копии, у сохранённых старых наборов их может быть ноль.')],
    recap: ["API, контроллеры, планировщик и kubelet выполняют разные части управления приложением.","В etcd хранится состояние Kubernetes; данные томов приложения требуют отдельного копирования."], exercise: 'Запрос apply прошёл, но у Pod не назначен узел. Начнёте ли вы с журналов веб-сервера? Нет: сначала проверьте условия планирования и события, потому что процесс мог ещё не запускаться.', question: 'Какой компонент выбирает узел для ещё не назначенного Pod?', options: ['Планировщик', 'Service', 'ConfigMap'], answer: 0, answerExplanation: 'Планировщик выбирает узел, а kubelet выбранного узла организует выполнение контейнеров.' }),
  L({ id: 'deployment-models', module: 'Устройство и управление', title: "Способы развёртывания и расчёт размера кластера", tag: 'Топология и ответственность',
    goal: 'Различать учебный кластер, самостоятельно обслуживаемую систему и управляемую облачную услугу.',
    introduction: ["Прежде чем устанавливать Kubernetes, следует определить, кто будет обслуживать управляющие компоненты, какую нагрузку предстоит размещать и какие отказы должна переносить система. Управляемая облачная услуга и самостоятельно устанавливаемый кластер распределяют эти обязанности по-разному. Выбор зависит от требований организации и доступных средств сопровождения.","Сравним способы установки, затем рассчитаем ресурсы для заданного приложения с учётом системных компонентов и резерва. Отдельно рассмотрим назначение пулов узлов и нескольких кластеров. Minikube в данном случае служит средством изучения; полученный расчёт не следует переносить на рабочую систему без измерений её приложений."],
    terms: [['Управляемый кластер', 'Часть обслуживания выполняет поставщик услуги; точная граница зависит от договора и продукта.'], ['Топология', 'Расположение управляющих и рабочих узлов по машинам и зонам отказа.'], ['Доступные ресурсы (Allocatable)', 'Объём узла, который Kubernetes может распределять между Pod после системных резервов.'], ['Зона отказа', 'Группа компонентов, которые могут выйти из строя по одной общей причине.']],
    sections: [R("Требования к установке", ['Запишите требования к доступности, допустимой потере данных, времени восстановления, размещению и доступу пользователей. Затем определите, кто обслуживает управляющие узлы, рабочие узлы, сеть, диски и обновления. Управляемая услуга обычно не снимает ответственность за настройки ваших приложений и их резервные копии.', 'Три управляющих экземпляра на одном физическом компьютере не дают защиту от отказа этого компьютера. Учитывайте общие питание, сеть, диски и площадку. Для etcd важен кворум: работоспособное большинство участников. Увеличение количества узлов требует понимания отказов и задержек, а не только бюджета.']), R("Расчёт ресурсов", ['Начинайте с запросов контейнеров, пикового числа копий и запаса на обновление. Если три контейнера запрашивают по 48Mi, это 144Mi запросов приложения, к которым добавляются системные службы, другие приложения и временные дополнительные копии. Реальная нагрузка измеряется отдельно.', 'При выборе самостоятельной установки нужны повторяемая автоматизация, управление версиями конфигурации, наблюдение за состоянием и проверенное восстановление. Запишите, где хранится конфигурация и как создать замену узла. Ручная последовательность неизвестных команд на единственном сервере не является планом эксплуатации.'])],
    steps: [S('Посмотрите характеристики узла', `${cluster} describe node kubelab`, 'Найдите Capacity, Allocatable и список размещённых Pod. Эти разделы показывают разные величины.', [['describe node kubelab', 'Подробное описание нашего единственного узла.']], 'Сравните полную ёмкость с доступной. Запишите процессор, память и уже заявленные ресурсы.', 'Имя узла возьмите из get nodes, если в вашей установке оно отличается.'), S('Проверьте версии клиента и сервера', `${cluster} version -o yaml`, 'Для обслуживания нужно знать обе версии и соблюдать допустимую разницу версий инструментов.', [['version -o yaml', 'Показать сведения о клиенте и доступном сервере в подробном виде.']], 'Видны clientVersion и serverVersion; запишите их для плана обновления.')],
    recap: ["Способ установки определяет распределение обязанностей по обслуживанию платформы.","Размер кластера рассчитывается с учётом приложений, системных расходов и допустимых отказов."], exercise: 'Составьте таблицу для учебного проекта: компонент, кто обслуживает, как обнаружить отказ, откуда восстановить. Для тома приложения и etcd заполните отдельные строки.', question: 'Что нужно выяснить при выборе управляемого кластера?', options: ['Какие обязанности остаются у нашей команды', 'Можно ли больше не делать резервные копии приложения', 'Будут ли любые три контейнера считаться тремя зонами отказа'], answer: 0, answerExplanation: 'Набор предоставляемых услуг ограничен. Приложения, доступ и данные требуют своей ответственности.' }),
  L({ id: 'runtime', module: 'Устройство и управление', title: "Образ контейнера и среда выполнения", tag: 'Контейнеры на узле',
    goal: 'Понять, почему Docker-драйвер Minikube и среда запуска контейнеров внутри узла — разные настройки.',
    introduction: ["Образ описывает содержимое контейнера, тогда как среда выполнения отвечает за создание и запуск процесса. В локальном окружении к этому добавляется ещё один уровень: Docker запускает окружение узла Minikube, а внутри узла Kubernetes обращается к своей среде выполнения контейнеров.","Рассмотрим эти уровни по отдельности и найдём сведения о среде выполнения в описании узла. Затем вернёмся к связи образа и запущенного процесса. Повторная сборка под прежним тегом меняет доступное содержимое образа, но не пересоздаёт уже работающий контейнер; для обновления нужен предусмотренный порядок замены Pod."],
    terms: [['Среда выполнения контейнеров', 'Службы узла, получающие запрос на создание контейнера и запускающие его процесс.'], ['Интерфейс выполнения контейнеров (CRI)', 'Способ взаимодействия kubelet со средой выполнения.'], ['Стандарт образа (OCI)', 'Общие форматы и правила, благодаря которым один формат образа поддерживают разные инструменты.'], ['Digest', 'Ссылка на содержимое образа по криптографическому хешу, в отличие от перемещаемого тега.']],
    sections: [R("Уровни среды выполнения", ['Параметр --driver=docker относится к созданию локального узла. Значение containerRuntimeVersion в объекте Node относится к контейнерам, запускаемым Kubernetes внутри узла. Не делайте вывод о втором только по первому.', 'Формат образа не обязан совпадать с названием программы, которой вы его собрали. Важны совместимость формата, архитектура процессора, операционная система и наличие образа в нужном месте. Образ Linux не превращается в программу Windows после изменения тега.']), R("Образ и работающий контейнер", ['Образ — подготовленное содержимое для запуска. Контейнер — конкретный экземпляр процесса на его основе. Если уже работающий контейнер использовал прежнее содержимое, переназначение тега в хранилище не заменит его процесс автоматически.', 'Для повторяемой доставки присваивайте каждой сборке уникальное обозначение и, когда требуется точная привязка, используйте digest. При политике Never образ должен уже находиться на каждом подходящем узле. При политике загрузки из реестра дополнительно нужны доступ, доверенные сертификаты и необходимые учётные данные.'])],
    steps: [S('Прочитайте среду выполнения узла', `${cluster} get node kubelab -o jsonpath='{.status.nodeInfo.containerRuntimeVersion}'`, 'Выводим одно поле вместо всего YAML. Значение определяется настоящей настройкой вашего профиля.', [['-o jsonpath', 'Выбрать значение по пути внутри объекта.'], ['status.nodeInfo.containerRuntimeVersion', 'Поле со средой выполнения и её версией.']], 'Например, containerd://… или другой настроенный вариант. Название из примера не является обязательным ответом.'), S('Проверьте локальный образ профиля', 'minikube image ls -p kubelab', 'Сверяем наличие образа там, где Kubernetes будет его искать в нашем опыте.', [['-p kubelab', 'Выбрать хранилище образов нужного профиля.']], 'В списке есть kubelab:1.0, возможно с префиксом реестра.')],
    recap: ["Драйвер Minikube и среда выполнения контейнеров узла относятся к разным уровням окружения.","Изменение содержимого тега не обновляет уже работающий процесс."], exercise: 'На первом узле образ есть, на втором нет, политика Never. Что произойдёт при размещении Pod на втором? Создание контейнера остановится на поиске образа; файл Deployment может быть полностью правильным.', question: 'Что выбирает --driver=docker?', options: ['Способ создания окружения узла Minikube', 'Обязательное название среды выполнения внутри любого кластера', 'Версию приложения'], answer: 0, answerExplanation: 'Драйвер относится к локальному окружению Minikube. Сведения о среде выполнения получаем отдельно.' }),
  L({ id: 'api-identity', module: 'Устройство и управление', title: "Обработка запроса к API и удостоверение клиента", tag: 'Идентификация и допуск',
    goal: 'Различать установление личности, проверку прав, изменение запроса и проверку допустимости объекта.',
    introduction: ["При обращении к Kubernetes сервер должен установить личность клиента, проверить его разрешения и определить допустимость переданного объекта. Это последовательные операции. Успешный вход не даёт права на любое действие, а разрешённое действие может быть отклонено на этапе проверки содержимого объекта.","Разберём устройство kubeconfig и связь контекста с кластером и учётными данными. Затем рассмотрим аутентификацию, авторизацию и допуск запроса, включая внешние обработчики. Пробное применение поможет проверить часть требований, однако запуск приложения, его сеть и внешние зависимости потребуют последующих проверок."],
    terms: [['Аутентификация', 'Проверка того, кто отправил запрос.'], ['Авторизация', 'Проверка того, разрешено ли этой личности запрошенное действие.'], ['Проверка допуска', 'Проверки и возможные изменения принимаемого объекта перед его сохранением.'], ['Внешний обработчик допуска (webhook)', 'Служба, к которой сервер обращается при проверке или изменении запросов; её доступность влияет на приём объектов.']],
    sections: [R("Этапы обработки запроса", ['Сначала устанавливается защищённое соединение и проверяются учётные данные. Затем система авторизации решает, разрешено ли действие. На этапе допуска запрос может быть дополнен значениями или отклонён по правилам. Проверяется и соответствие схеме. Только принятый объект сохраняется.', 'Например, администратор может иметь право создавать Pod, но конфигурация с повышенными привилегиями всё равно будет отклонена политикой безопасности. Назначение ещё более широкой роли не решает эту проблему: нужно исправить сам объект или обоснованно пересмотреть политику.']), R("Настройки подключения", ['Контекст kubectl выбирает кластер, пользователя и пространство имён по умолчанию. Файл настроек подключения может содержать сертификаты, токены или ссылки на программы получения учётных данных. Его нельзя публиковать в отчёте об ошибке. Команду config view --raw для демонстрации мы не используем.', 'Проверяйте время действия сертификатов и токенов, доверие к центру сертификации и точное имя сервера. Отключение проверки сертификата скрывает важную проверку подлинности. Для внешнего поставщика идентичности отдельно нужны правила жизненного цикла учётных записей, групп и отзыва доступа.']), R("Пробное применение", ['--dry-run=server выполняет серверные проверки без сохранения объектов. Это полезнее одной проверки синтаксиса, но не запускает контейнер и не проверяет доступ к образу, диску или внешней базе. Успешная проба не заменяет rollout status и проверку приложения.'])],
    steps: [S('Проверьте своё разрешение', `${k} auth can-i create deployments`, 'Спрашиваем о конкретном действии текущей учётной записи.', [['auth can-i create deployments', 'Проверка возможности создания Deployment в выбранном пространстве имён.']], 'В стандартном Minikube владельца ожидается yes. В ограниченном кластере no может быть правильным результатом политики.'), S('Выполните серверную пробу', `${cluster} apply --dry-run=server -f k8s/lab.yaml`, 'Сервер проверит известные ему виды, поля и правила допуска, но не сохранит изменения из файла.', [['--dry-run=server', 'Серверная проверка без сохранения.']], 'Строки объектов содержат dry run. Число реплик и сообщение работающего приложения не меняются.')],
    recap: ["Аутентификация устанавливает личность, авторизация проверяет действие, допуск проверяет объект.","Kubeconfig и его контекст задают адрес назначения и используемую учётную запись."], exercise: 'Сервер отвечает, что Pod нарушает restricted. Нужно ли выдавать cluster-admin? Нет: сначала разберите запрещённые поля и приведите описание к требованиям.', question: 'Проверяет ли успешный dry-run запуск контейнера?', options: ['Нет, объект проверяется без запуска', 'Да, контейнер запускается и сразу удаляется', 'Да, проверяются все внешние зависимости'], answer: 0, answerExplanation: 'Проба выполняет серверные проверки объекта, но не исполняет рабочую нагрузку.' }),
  L({ id: 'lifecycle', module: 'Жизнь приложения', title: "Завершение работы контейнера", tag: 'Жизненный цикл Pod', files: ['lifecycle'],
    goal: 'Проследить запуск, сигнал завершения и отведённое процессу время.',
    introduction: ["При удалении Pod приложение должно прекратить приём новых задач и по возможности завершить уже начатые. Для этого недостаточно только выделить некоторое число секунд. Процесс должен обрабатывать сигнал завершения, а Kubernetes — предоставлять подходящий промежуток времени до принудительной остановки.","В примере запустим процесс, который получает SIGTERM, выполняет завершающее действие и выходит. По журналу проследим порядок событий. Далее рассмотрим preStop и terminationGracePeriodSeconds: время обработчика preStop входит в общий срок завершения Pod, поэтому его нельзя считать дополнительным независимым запасом."],
    terms: [['SIGTERM', 'Сигнал с просьбой корректно завершить процесс. Программа должна уметь его обработать.'], ['Период завершения', 'Время до принудительной остановки, заданное terminationGracePeriodSeconds.'], ['Обработчик preStop', 'Действие перед завершением контейнера; оно тоже расходует общий период завершения.'], ['Финализатор', 'Метка обязательной очистки объекта контроллером перед окончательным удалением; это не обработчик сигнала процесса.']],
    sections: [R("Срок корректного завершения", ['В учебном файле установлен период 10 секунд, а программа завершается примерно за секунду после сигнала. Это позволяет показать последовательность. Для реального сервера время выбирают по длительности запросов, остановке очередей и требованиям клиентов.', 'При остановке готовность и распространение сетевого состояния меняются не строго одновременно. Клиенты могут иметь уже открытые соединения. Приложению нужны собственная обработка остановки, разумные таймауты и повторяемость операций. Бесконечный sleep в preStop не является надёжным способом завершения.']), R("Наблюдение за остановкой", ['Журнал читается, пока Pod существует. После удаления получить его обычной командой logs уже нельзя. Для долговременной диагностики журналы нужно собирать до удаления во внешнее хранилище.', 'В одной встроенной консоли мы сначала прочитаем стартовое сообщение, затем удалим Pod с ожиданием. Сам обработчик сигнала можно дополнительно наблюдать из второго обычного терминала через logs -f до удаления. Здесь не открываем два параллельных процесса в одной консоли и не обещаем сохранить удалённые журналы.'])],
    steps: [apply('lifecycle', 'Создаём отдельный Pod, который не управляется Deployment и после удаления не появится снова.', 'Pod kubelab-lifecycle создан.'), S('Прочитайте сообщение запуска', `${k} logs pod/kubelab-lifecycle --pod-running-timeout=120s`, 'Дожидаемся процесса и читаем его стартовое сообщение.', [['--pod-running-timeout=120s', 'Разрешить контейнеру время на запуск.']], 'В журнале есть started.'), remove('lifecycle', 'Удаление отправляет процессу сигнал и ожидает завершения. Этот самостоятельный Pod не восстанавливается контроллером.')],
    recap: ["Корректное завершение требует согласованной работы приложения и настроек Pod.","PreStop использует общий срок terminationGracePeriodSeconds."], exercise: 'Процесс завершает запрос 20 секунд, а период остановки равен 10. Почему одной обработки SIGTERM недостаточно? Время закончится раньше обработки; нужны согласованные таймауты и поведение клиента.', question: 'Когда приложение должно подготовиться к остановке?', options: ['После получения сигнала завершения, в пределах выделенного времени', 'Только после принудительного уничтожения процесса', 'Kubernetes закончит любой запрос сам'], answer: 0, answerExplanation: 'Состояние и протокол знает приложение. Kubernetes ограничивает время, но не выполняет бизнес-операции за него.' }),
  L({ id: 'scheduling', module: 'Жизнь приложения', title: "Размещение Pod на узлах", tag: 'Планирование', files: ['scheduling'],
    goal: 'Связать метки узла, запросы ресурсов, ограничения размещения и события планировщика.',
    introduction: ["Планировщик выбирает узел для Pod, учитывая ресурсы и ограничения размещения. Часть требований обязательна, например наличие нужной метки. Другие параметры выражают предпочтение, которое учитывается только среди допустимых вариантов. Смешение этих двух видов условий затрудняет диагностику состояния Pending.","Опишем требование к узлу и посмотрим, как оно отражается на размещении. Если подходящих узлов нет, обратимся к событиям Pod и проверим каждое условие. Добавление вычислительных ресурсов поможет только в том случае, если новый узел также соответствует ограничениям приложения и его хранилища."],
    terms: [['Метка узла', 'Пара ключ–значение на объекте Node, используемая в правилах размещения.'], ['nodeSelector', 'Обязательное совпадение с указанными метками узла.'], ['Сродство (affinity)', 'Более выразительные обязательные или предпочтительные правила размещения.'], ['Ограничение узла (taint) и допуск (toleration)', 'Механизм отталкивания Pod от узла и разрешение выдержать такое ограничение; допуск сам по себе не выбирает узел.']],
    sections: [R("Обязательные требования и предпочтения", ['nodeSelector — требование. Если ни один узел ему не соответствует, Pod может оставаться Pending сколько угодно. Добавление памяти не исправит отсутствующую метку. В nodeAffinity также различаются обязательные и предпочтительные правила: предпочтение допускает другой вариант, требование нет.', 'Pod affinity и anti-affinity сравнивают расположение с другими Pod. Их используют для совместного размещения или разнесения по узлам и зонам. На единственном узле нельзя доказать разнесение двух копий на разные компьютеры; обязательное правило может сделать вторую копию неразмещаемой.']), R("Причины ожидания назначения", ['Сначала проверьте назначение узла в get pods -o wide. Затем читайте события FailedScheduling: нехватка процессора, несоответствие меткам и неподходящий том требуют разных исправлений. Учитываются запросы ресурсов, а не только фактическая загрузка в данный момент.', 'В рабочем проекте храните собственные метки размещения в управляемой конфигурации. Не подменяйте системные метки ради прохождения опыта. Прямая запись nodeName обходит обычный выбор планировщика и не является общим решением нехватки места.'])],
    steps: [S('Покажите метки узлов', `${cluster} get nodes --show-labels`, 'Найдите kubernetes.io/os=linux. Список меток может быть длинным.', [['--show-labels', 'Добавить к таблице метки каждого узла.']], 'Учебный узел Linux имеет нужную метку.'), apply('scheduling', 'Создаём отдельный Deployment с обязательным условием ОС.', 'Deployment kubelab-placement создан.'), S('Посмотрите место запуска', `${k} get pods -l app=kubelab-placement -o wide`, 'Фильтруем только Pod этого опыта и читаем колонку NODE.', [['-l app=kubelab-placement', 'Выбрать Pod отдельного приложения.'], ['-o wide', 'Показать дополнительные поля, включая узел и адрес.']], 'После размещения в NODE указан kubelab. Если Pending, прочитайте новые события.'), remove('scheduling', 'Удаляем только отдельный опыт размещения.')],
    recap: ["Обязательные требования исключают неподходящие узлы, а предпочтения определяют выбор среди оставшихся.","Причину ожидания назначения следует искать в событиях и условиях размещения Pod."], exercise: 'Два Pod требуют размещения на разных узлах, а узел один. Какой честный результат? Второй Pod может остаться Pending; изменение числа реплик не создаёт новый узел.', question: 'Гарантирует ли toleration размещение на определённом узле?', options: ['Нет, он только допускает соответствующее ограничение', 'Да, всегда', 'Да, если имя совпадает с Deployment'], answer: 0, answerExplanation: 'Toleration снимает конкретный запрет, но выбор определяется и другими условиями.' }),
  L({ id: 'batch', module: 'Жизнь приложения', title: "Однократные и периодические задания", tag: 'Job и CronJob', files: ['batch'],
    goal: 'Запустить одноразовый отчёт и разобрать расписание без постоянного веб-сервера.',
    introduction: ["Не всякая программа должна работать постоянно. Отчёт, перенос данных или очистка временных файлов завершаются после выполнения задачи. В Kubernetes для конечной работы используется Job, а для её запуска по расписанию — CronJob. Эти объекты иначе определяют успешный результат, чем Deployment веб-сервера.","Рассмотрим полные описания задания и расписания: число повторных попыток, запрет одновременных запусков и хранение истории. Периодическое задание в примере первоначально приостановлено. Перед его включением важно понять, допускает ли сама операция повторное выполнение и как приложение обнаруживает уже обработанную работу."],
    terms: [['Job', 'Контроллер выполнения конечной задачи до нужного числа успешных завершений.'], ['CronJob', 'Контроллер создания Job по расписанию.'], ['backoffLimit', 'Ограничение числа повторных попыток после неудач.'], ['Идемпотентная задача', 'Повторное выполнение которой не создаёт повторного нежелательного эффекта, например двойного списания.']],
    sections: [R("Параметры расписания", ['schedule: */5 * * * * означает запуск раз в пять минут. timeZone: Etc/UTC делает часовой пояс явным. concurrencyPolicy: Forbid запрещает этому CronJob создавать новый параллельный запуск, пока предыдущий ещё выполняется. Это не блокировка всех задач в кластере.', 'restartPolicy: Never позволяет контроллеру Job создавать новые попытки отдельными Pod. backoffLimit: 1 ограничивает повторения. Число попыток и расписание не дают гарантии «ровно один раз»: программа должна корректно переживать повторы и частичное выполнение.']), R("Условия завершения задания", ['Job отслеживает завершение контейнера с успешным кодом. Он не знает, правильный ли отчёт был отправлен пользователю. Контроль результата и защита от повторного эффекта остаются в программе.', 'Успешный Pod имеет Completed, и READY обычно равен 0/1. Для такой задачи это нормальный конец. История успешных и неудачных Job ограничивается отдельными полями CronJob; отдельно продумайте срок хранения результатов и журналов.'])],
    steps: [apply('batch', 'Создаём один конечный отчёт и описание приостановленного расписания.', 'Созданы job/kubelab-report и cronjob/kubelab-schedule.'), S('Дождитесь завершения отчёта', `${k} wait --for=condition=complete job/kubelab-report --timeout=120s`, 'Здесь проверяем условие Job, а не rollout Deployment.', [['--for=condition=complete', 'Ожидать успешного завершения работы.']], 'condition met. При ошибке смотрите Pod Job и его журнал.'), S('Прочитайте результат', `${k} logs job/kubelab-report`, 'Получаем вывод контейнера выполненной задачи.', [['logs job/kubelab-report', 'Найти Pod данного Job и прочитать его вывод.']], 'Строка JSON с report: learning и rows: 3.'), S('Проверьте приостановленное расписание', `${k} get cronjob kubelab-schedule`, 'Убедитесь, что мы не оставляем автоматические запуски после чтения урока.', [['SUSPEND', 'Признак приостановки создания новых Job по расписанию.']], 'SUSPEND True. Отсутствие новых запусков здесь ожидаемо.'), remove('batch', 'Удаляем учебную задачу и расписание вместе с их управляемыми Pod.')],
    recap: ["Job предназначен для конечной задачи, CronJob создаёт задания по расписанию.","Повторный запуск и ограничение параллельности должны соответствовать устройству самой операции."], exercise: 'Задача записала половину данных и упала. Что должен учитывать повтор? Он должен определить уже выполненную часть или безопасно повторить запись, а не безусловно дублировать результат.', question: 'Что создаёт CronJob по расписанию?', options: ['Job', 'Новый кластер', 'Новую версию образа'], answer: 0, answerExplanation: 'CronJob создаёт конечные задания. Поведение их программы задаётся шаблоном.' }),
  L({ id: 'stateful', module: 'Хранение данных', title: "Состояние приложения и StatefulSet", tag: 'StatefulSet', files: ['stateful'], minutes: 55,
    goal: 'Связать порядковое имя Pod, внутреннее сетевое имя и отдельную заявку на том.',
    introduction: ["Некоторым приложениям важны устойчивые имена экземпляров и отдельное хранилище для каждого из них. Это характерно, например, для систем, участники которых обмениваются данными под постоянными именами. StatefulSet предоставляет упорядоченные имена Pod и связь с индивидуальными заявками на тома.","Создадим несколько экземпляров с такими заявками и рассмотрим их имена, адреса и сохранность данных после замены Pod. При этом сам StatefulSet не реализует репликацию базы данных или восстановление её согласованного состояния. Эти обязанности остаются у приложения и средств его сопровождения."],
    terms: [['StatefulSet', 'Контроллер Pod с устойчивыми порядковыми именами и связью с отдельными заявками на том.'], ['Сервис без общего адреса (headless Service)', 'Service с clusterIP: None, позволяющий получать адреса экземпляров через службу имён.'], ['volumeClaimTemplates', 'Шаблоны отдельных заявок для экземпляров StatefulSet.']],
    sections: [R("Устойчивые имена и хранилище", ['Имена экземпляров будут kubelab-stateful-0 и kubelab-stateful-1. После замены экземпляр с тем же порядковым номером может подключить свою прежнюю заявку. Это отличается от произвольного нового имени Pod в обычном Deployment.', 'serviceName связывает StatefulSet с управляющим headless Service. Точный состав адресов зависит от готовности Pod и работы службы имён. В отличие от обычного ClusterIP, здесь нет одного виртуального адреса для всех получателей.']), R("Обязанности приложения", ['Он не выбирает главную реплику базы данных, не копирует транзакции и не предотвращает конфликт двух писателей. Доступность и согласованность требуют прикладного протокола и часто специального оператора.', 'В примере две заявки по 200Mi. Один диск не становится автоматически общим для двух экземпляров. При удалении StatefulSet заявки по умолчанию сохраняются. Это защищает от случайного удаления данных, но требует явного решения о последующей очистке. В конце опыта мы отдельно удалим только две учебные заявки.'])],
    steps: [apply('stateful', 'Создаём headless Service и StatefulSet с двумя отдельными томами.', 'Оба объекта созданы; предоставление томов может занять время.'), S('Дождитесь экземпляров', `${k} rollout status statefulset/kubelab-stateful --timeout=180s`, 'Проверяем обновление StatefulSet, а не одноимённый Deployment.', [['statefulset/kubelab-stateful', 'Выбрать контроллер этого опыта.']], 'Обе копии готовы. При ожидании проверьте заявки и события.'), S('Прочитайте имена и узлы', `${k} get pods -l app=kubelab-stateful -o wide`, 'Сравните имена с произвольными именами Pod Deployment.', [['-l app=kubelab-stateful', 'Только экземпляры StatefulSet.']], 'Видны имена с окончаниями -0 и -1.'), S('Покажите отдельные заявки', `${k} get pvc`, 'Найдите notes-kubelab-stateful-0 и notes-kubelab-stateful-1.', [['get pvc', 'Список заявок учебного пространства имён.']], 'Две отдельные заявки Bound; их тома различаются.'), remove('stateful', 'Удаляем Service и StatefulSet. Заявки этого опыта по умолчанию остаются.'), S('Удалите две учебные заявки', `${k} delete pvc notes-kubelab-stateful-0 notes-kubelab-stateful-1`, 'Это отдельное осознанное удаление данных двух учебных экземпляров. Для важных данных сначала нужна проверенная резервная копия.', [['delete pvc', 'Удалить только две перечисленные заявки.']], 'Обе учебные заявки удалены. При политике Delete тома и их содержимое также будут удалены.')],
    recap: ["StatefulSet предоставляет устойчивые имена и отдельные заявки на хранение для экземпляров.","Репликация и согласованность данных требуют поддержки приложения."], exercise: 'Почему две копии произвольной базы нельзя безопасно соединить с одним диском только изменением replicas? Общий диск не реализует протокол одновременной записи и согласованности.', question: 'Гарантирует ли StatefulSet резервное копирование базы?', options: ['Нет, это отдельная задача', 'Да, при replicas: 2', 'Да, если есть headless Service'], answer: 0, answerExplanation: 'Устойчивые идентичности и заявки не заменяют механизм резервного копирования.' }),
  L({ id: 'storage-operations', module: 'Хранение данных', title: "Свойства хранилища и восстановление данных", tag: 'Классы, снимки и копии',
    goal: 'Прочитать свойства поставщика томов и отличить снимок диска от проверенной резервной копии.',
    introduction: ["Постоянный том решает задачу сохранения данных при замене Pod, но требования к хранению этим не исчерпываются. Приложению могут понадобиться расширение, снимки, заданная производительность и восстановление после потери узла. Возможность выполнить эти действия зависит от класса и поставщика хранилища.","Рассмотрим StorageClass, режимы доступа и политику освобождения тома, затем составим порядок проверки резервной копии. Важно установить, какие данные попадают в копию, где она размещена и как из неё запускается приложение. Копия на том же компьютере позволяет проверить процедуру, но не защищает от потери этого компьютера."],
    terms: [['Поставщик томов', 'Компонент, предоставляющий хранилище по заявкам.'], ['Интерфейс хранения (CSI)', 'Стандарт взаимодействия Kubernetes с подключаемыми системами хранения.'], ['Политика возврата', 'Определяет судьбу тома после освобождения заявки, например Delete или Retain.'], ['Снимок', 'Состояние тома в определённый момент, если поставщик и дополнительные компоненты поддерживают снимки.']],
    sections: [R("Свойства StorageClass", ['provisioner показывает механизм выделения. reclaimPolicy определяет дальнейшую судьбу освобождённого тома. volumeBindingMode влияет на момент привязки: немедленно или с учётом размещения первого потребителя. allowVolumeExpansion разрешает запрос увеличения при наличии поддержки поставщика.', 'Изменение storage в заявке не гарантирует мгновенное расширение файловой системы. Уменьшение обычно не поддерживается тем же способом. Нельзя универсально копировать настройки облачного диска в локальный Minikube: разные поставщики имеют разные возможности и ограничения.']), R("Подготовка резервной копии", ['Определите допустимую потерю данных и время восстановления. Для базы данных используйте согласованную копию её средствами либо поддерживаемый способ остановки записи. Произвольная копия файлов активной базы может быть непригодна.', 'Храните копии отдельно от исходного диска и проверяйте восстановление в отдельном окружении. Записывайте версию программы, схему, необходимые настройки и зависимости. Снимок в той же системе хранения не обязательно защищает от её полной потери или удаления учётной записи.']), R("Условия локального примера", ['Ранее мы проверили сохранение заметки после замены Pod. Здесь расширяем перечень проверок: потеря Pod, потеря узла, удаление заявки, потеря диска и восстановление на другом окружении — разные сценарии. Для каждого укажите способ проверки и ожидаемую границу сохранности.', 'В Minikube наличие объектов VolumeSnapshot не гарантировано. Даже если такой вид установлен, нужен совместимый драйвер и контроллер снимков. Не называйте вывод get storageclass доказательством созданной резервной копии.'])],
    steps: [S('Прочитайте настройки классов', `${cluster} get storageclass -o yaml`, 'Смотрите реальные provisioner, reclaimPolicy, volumeBindingMode и поддержку расширения.', [['-o yaml', 'Полное описание доступных классов без изменения настроек.']], 'Для локального Minikube обычно виден локальный поставщик, а не распределённое облачное хранилище.'), S('Проверьте постоянные тома', `${cluster} get persistentvolumes`, 'Тома относятся ко всему кластеру. После очистки прежнего опыта список может быть пуст.', [['get persistentvolumes', 'Показать предоставленные тома, включая их состояние и политику.']], 'Прочитайте STATUS, RECLAIM POLICY и STORAGECLASS. Пустой список после удаления учебных заявок допустим.')],
    recap: ["Свойства тома определяются реализацией хранилища и настройками StorageClass.","Пригодность резервной копии подтверждается восстановлением и проверкой данных."], exercise: 'Составьте процедуру: где копия, как проверить её целостность, где развернуть восстановление, как проверить приложение и кто разрешает замену исходной системы. Это задание на план восстановления, а не утверждение, что резервная копия уже создана.', question: 'Достаточно ли наличия снимка для доказательства восстановимости?', options: ['Нет, нужно проверить восстановление и согласованность приложения', 'Да, всегда', 'Да, если снимок сделан недавно'], answer: 0, answerExplanation: 'Существование копии не доказывает полноту данных и возможность запуска приложения.' })
];
advancedLessons.push(
  L({ id: 'autoscaling', module: 'Наблюдение и масштабирование', title: "Автоматическое изменение числа реплик", tag: 'Автоматическое число копий', files: ['autoscale'],
    before: 'Пройдите занятие о метриках и убедитесь, что top pods получает данные. Если служба метрик недоступна, сначала исправьте её; неизвестные измерения нельзя считать нулевой нагрузкой. По завершении удалим правило и вернём три учебные копии.',
    goal: 'Прочитать цель масштабирования и проверить, откуда контроллер получает значения.',
    introduction: ["Нагрузка на приложение редко остаётся постоянной. Контроллер HorizontalPodAutoscaler, или HPA, изменяет число реплик на основании измеряемого показателя и заданной цели. Результат зависит от доступности метрик и от того, может ли приложение распределить работу между дополнительными экземплярами.","Рассмотрим цель по использованию процессора и её связь с requests контейнера. Затем проверим состояние HPA и причины, по которым вычисление или масштабирование может быть недоступно. Новые реплики также потребуют места на узлах, поэтому увеличение числа Pod следует рассматривать вместе с ёмкостью кластера."],
    terms: [['HorizontalPodAutoscaler', 'Контроллер горизонтального изменения числа экземпляров по измерениям.'], ['Вертикальное масштабирование', 'Изменение ресурсов одной копии; не то же самое, что добавление Pod.'], ['Масштабирование узлов', 'Изменение вычислительной ёмкости кластера; дополнительные Pod сами новые узлы не создают.']],
    sections: [R("Настройка цели HPA", ['scaleTargetRef указывает Deployment kubelab. minReplicas: 2 и maxReplicas: 4 задают допустимые границы. averageUtilization: 60 при запросе контейнера 50m означает цель около 30m среднего процессорного времени на копию, а не 60 процентов лимита 250m и не всего компьютера.', 'Для ресурсной доли нужны корректные requests соответствующих контейнеров и доступные метрики. Контроллер учитывает готовность, неполные измерения и стабилизацию. Изменения происходят постепенно; один пик не обязан немедленно привести к максимальному числу копий.']), R("Условия полезного масштабирования", ['Если приложение ограничено внешней базой, добавление копий может усилить очередь и не уменьшить задержку. Если на узле нет места для новых запросов, дополнительные Pod останутся Pending. Тогда нужно отдельно решить вопрос ёмкости, а не увеличивать maxReplicas бесконечно.', 'Не смешивайте без плана контроллер, ручной scale и постоянное применение файла с фиксированными replicas. Каждый может менять одно поле. В рабочей доставке определяют, кто отвечает за число копий. При вертикальном управлении также учитывают возможную замену Pod и совместимость с горизонтальным правилом.'])],
    steps: [apply('autoscale', 'Создаём правило для существующего приложения, не отдельную копию сервера.', 'HorizontalPodAutoscaler kubelab-scale создан.'), S('Прочитайте цель и измерение', `${k} get hpa kubelab-scale`, 'Сравните TARGETS, MINPODS, MAXPODS и REPLICAS.', [['get hpa', 'Короткое имя ресурса автоматического масштабирования.']], 'После появления измерений видна доля процессора. Сразу после создания возможно unknown; это не ноль.'), S('Посмотрите условия решения', `${k} describe hpa kubelab-scale`, 'Условия и события объясняют, получает ли контроллер метрики и может ли менять размер.', [['describe hpa', 'Подробности работы правила и недавние причины решений.']], 'Проверьте AbleToScale, ScalingActive и отсутствие ошибок получения данных.'), remove('autoscale', 'Останавливаем именно автоматическое управление числом копий.'), S('Верните три копии', `${k} scale deployment/kubelab --replicas=3`, 'Теперь число копий снова задаётся вручную. Манифест на диске по-прежнему имеет своё значение.', [['--replicas=3', 'Желаемое число экземпляров после опыта.']], 'Deployment scaled.')],
    recap: ["HPA сопоставляет измеренный показатель с целью и управляет числом реплик.","Доступность метрик, requests и возможность размещения ограничивают результат масштабирования."], exercise: 'Запрос равен 100m, цель 60 процентов. Какое среднее соответствует цели? Около 60m на копию. Изменение запроса меняет смысл той же процентной цели.', question: 'Что означает unknown в TARGETS?', options: ['Подходящее измерение пока не получено', 'Нагрузка равна нулю', 'Нужно удалить все Pod'], answer: 0, answerExplanation: 'Отсутствие данных нельзя подменять значением ноль.' }),
  L({ id: 'cluster-maintenance', module: 'Эксплуатация и доставка', title: "Обслуживание узлов и доступность приложения", tag: 'Доступность и восстановление', files: ['disruption'],
    goal: 'Разделить обслуживание приложения, рабочего узла и управляющей системы.',
    introduction: ["Обслуживание узла предполагает перенос или завершение размещённых на нём работ. Для приложения с несколькими копиями необходимо установить, сколько экземпляров должно оставаться доступным во время таких действий. PodDisruptionBudget, или PDB, описывает ограничение добровольных вытеснений.","Разберём бюджет и его влияние на последовательность обслуживания. Затем составим порядок обновления узлов с проверкой приложения после каждого этапа. Одноузловой Minikube позволяет изучить настройки и возможные причины остановки операции, но не показывает отказоустойчивость приложения, распределённого по независимым серверам."],
    terms: [['Добровольное прерывание', 'Например, контролируемое выселение Pod при обслуживании узла.'], ['PodDisruptionBudget', 'Ограничивает допустимые добровольные выселения выбранных Pod.'], ['drain', 'Подготовка узла к обслуживанию через прекращение обычного размещения и выселение подходящих Pod.'], ['Проверка совместимости', 'Оценка поддерживаемых версий и используемых интерфейсов до обновления.']],
    sections: [R("Бюджет добровольных вытеснений", ['minAvailable: 1 означает требование сохранить хотя бы одну доступную копию среди выбранных Pod при учитываемых добровольных выселениях. Если копия одна, такое обслуживание может быть заблокировано. Это полезный сигнал о несоответствии плана требованию доступности.', 'Бюджет не предотвращает поломку узла и не гарантирует отсутствие перерыва при любых изменениях Deployment. В одноузловом Minikube все копии всё равно зависят от одной машины. Не называйте три Pod доказательством отказоустойчивости узлов.']), R("Порядок обновления", ['Зафиксируйте версии, используемые виды объектов, совместимость дополнений и допустимую разницу версий клиента и узлов. Проверьте копию управляющего состояния и отдельно данных приложения. Затем испытайте обновление и восстановление в другом окружении.', 'На рабочем кластере обновляют компоненты в поддерживаемом порядке и обслуживают узлы порциями с проверкой запаса ёмкости. Способ отката может требовать восстановления, а не простого указания старой версии. Не выполняйте универсальные команды kubeadm на узле, который установлен другим способом.']), R("Условия обслуживания Minikube", ['Для безопасного опыта остановка и запуск профиля сохраняют учебное состояние, а delete удаляет его. Обновление профиля и замена среды Minikube требуют своего плана, особенно для локальных данных.', "Результатом данного примера являются проверенный бюджет вытеснений и порядок обслуживания. Само обновление серверов выполняется в отдельном окружении. До такого испытания необходимо подготовить проверенную копию данных и установить допустимый перерыв, порядок возврата и признаки успешного восстановления."])],
    steps: [S('Зафиксируйте версии', `${cluster} version -o yaml`, 'Это исходные данные плана совместимости.', [['clientVersion и serverVersion', 'Запишите обе стороны подключения.']], 'Версии получены.'), apply('disruption', 'Добавляем бюджет только для учебных копий app: kubelab.', 'PodDisruptionBudget создан.'), S('Проверьте допустимые прерывания', `${k} get pdb kubelab-availability`, 'Колонка ALLOWED DISRUPTIONS зависит от текущей готовности и числа копий.', [['get pdb', 'Показать бюджет прерываний.']], 'При нескольких готовых копиях допустимое число может быть больше нуля. Ноль — причина изучить состояние перед обслуживанием.'), remove('disruption', 'Удаляем дополнительное учебное ограничение; узлы не выводились из обслуживания.')],
    recap: ["PDB ограничивает добровольные вытеснения с учётом доступности выбранных Pod.","Обновление узлов требует проверки приложений и доступной ёмкости для переноса."], exercise: 'Напишите критерий остановки обновления: например, новые Pod не готовы за согласованное время или ошибки превышают порог. Укажите, кто принимает решение и как восстановить данные.', question: 'Защищает ли PodDisruptionBudget от физического отказа единственного узла?', options: ['Нет', 'Да, если minAvailable равен 1', 'Да, если Pod три'], answer: 0, answerExplanation: 'Правило управляет определёнными добровольными выселениями, а не работой оборудования.' }),
  L({ id: 'helm', module: 'Эксплуатация и доставка', title: "Упаковка приложения с помощью Helm", tag: 'Helm и версии установки', assetPaths: ['charts/kubelab/Chart.yaml', 'charts/kubelab/values.yaml', 'charts/kubelab/templates/deployment.yaml'], minutes: 60,
    before: 'Helm — дополнительная программа этого модуля. Для реального выполнения установите её по официальной инструкции helm.sh/docs/intro/install, добавьте helm.exe в PATH и перезапустите KubeLab. Базовый установщик её не включает. Тренажёр не требует установленного Helm. Готовый пакет лежит в charts/kubelab.',
    goal: 'Проверить шаблон, установить отдельный пакет, изменить параметр и удалить только эту установку.',
    introduction: ["По мере увеличения числа объектов становится неудобно управлять каждым манифестом независимо. Helm объединяет связанные описания в пакет, который называется chart. Параметры пакета позволяют устанавливать одно приложение с разными значениями имени, числа копий и ссылки на образ.","Рассмотрим полный состав небольшого chart, затем установим его в учебное пространство и изменим параметр. Helm сохраняет историю установки, однако её следует отличать от данных самого приложения. Возврат прежней версии пакета меняет описания объектов и не отменяет несовместимые изменения в базе данных."],
    terms: [['Chart', 'Пакет с описанием, значениями и шаблонами ресурсов.'], ['Values', 'Параметры, которыми заполняют шаблоны.'], ['Release Helm', 'Конкретная установка пакета с собственным именем и историей. Это не GitHub-релиз приложения.']],
    sections: [R("Структура пакета Helm", ['Chart.yaml содержит имя и версию пакета. values.yaml задаёт replicaCount и image. В шаблоне .Values обращается к параметрам, а .Release.Name и .Release.Namespace — к выбранной установке. После обработки получается обычный манифест Kubernetes.', 'Произвольная строка {{ … }} не поддерживается самим Kubernetes. Нельзя отправить необработанный шаблон через kubectl apply и ожидать подстановку. Сначала Helm должен сформировать результат. Его нужно читать и проверять так же внимательно, как написанный вручную YAML.']), R("История установки и данные", ['Изменение replicaCount создаст следующую версию установки Helm и изменит Deployment. Это не обязано создавать новую ревизию шаблона Pod, если изменилось только число копий: история Helm и история Deployment отражают разные события.', 'Откат Helm не является универсальной отменой миграции базы данных. Секреты, тома и внешние изменения требуют собственного плана. Перед установкой стороннего пакета проверяйте источник, параметры безопасности, необходимые права и создаваемые объекты. Название популярного пакета не заменяет обзор результата.'])],
    steps: [S('Проверьте установленный Helm', 'helm version --short', 'В реальном режиме программа должна находиться в PATH.', [['version --short', 'Кратко показать версию без подключения к кластеру.']], 'Версия Helm. Если программа не найдена, завершите подготовку этого дополнительного компонента.'), S('Проверьте структуру пакета', 'helm lint charts/kubelab', 'Локальная проверка обнаруживает часть ошибок пакета до установки.', [['lint', 'Проверить пакет и шаблоны.']], 'Проверка завершилась без ошибок.'), S('Посмотрите получившийся манифест', 'helm template kubelab-package charts/kubelab --namespace kubelab', 'Обработка шаблона не создаёт объект. Проверьте имя, образ и число копий в результате.', [['template', 'Вывести сформированные ресурсы.'], ['--namespace kubelab', 'Пространство имён установки.']], 'Обычный Deployment kubelab-package с одной копией.'), S('Установите отдельный пакет', 'helm upgrade --install kubelab-package charts/kubelab --kube-context kubelab --namespace kubelab --wait --timeout 120s', 'Создаём или обновляем только эту именованную установку.', [['--kube-context kubelab', 'Подключение Helm к учебному кластеру.'], ['--wait', 'Ожидать готовность учитываемых ресурсов.']], 'Установка deployed. Основной Deployment не меняется.'), S('Измените параметр', 'helm upgrade kubelab-package charts/kubelab --kube-context kubelab --namespace kubelab --set replicaCount=2 --wait --timeout 120s', 'Формируется новая версия установки с двумя копиями.', [['--set replicaCount=2', 'Переопределить значение пакета для этой установки.']], 'Новая версия установки deployed.'), S('Покажите историю', 'helm history kubelab-package --kube-context kubelab --namespace kubelab', 'Посмотрите номера версий этой установки.', [['history', 'История установки Helm, не история Git и не rollout Deployment.']], 'В свежем опыте видны две версии; при повторениях их может быть больше.'), S('Удалите учебную установку', 'helm uninstall kubelab-package --kube-context kubelab --namespace kubelab', 'Пакет содержит только отдельный Deployment, поэтому не удаляет исходное приложение.', [['uninstall', 'Удалить ресурсы выбранной установки.']], 'Установка удалена.')],
    recap: ["Chart объединяет шаблоны объектов и их параметры в версионируемый пакет.","История Helm относится к установке и не заменяет восстановление данных."], exercise: 'Почему шаблон должен использовать имя установки в selector и метках одинаково? Иначе созданный контроллер не будет выбирать собственные Pod либо проверка схемы отклонит описание.', question: 'Что делает helm template?', options: ['Формирует документы без установки', 'Обязательно запускает приложение', 'Обновляет Minikube'], answer: 0, answerExplanation: 'Для запуска нужна отдельная операция установки и последующая проверка.' }),
  L({ id: 'kustomize', module: 'Эксплуатация и доставка', title: "Варианты конфигурации с Kustomize", tag: 'Kustomize', assetPaths: ['k8s/overlays/dev/kustomization.yaml'],
    goal: 'Сформировать настройку одного окружения без копирования всего общего манифеста.',
    introduction: ["Для нескольких окружений часто требуется общая основа манифестов с небольшими различиями. Например, число реплик в среде разработки может быть меньше, чем в рабочей системе. Kustomize формирует итоговое описание из основы и наложений, не требуя превращать каждый исходный файл в шаблон.","Просмотрим результат сборки наложения до его применения и найдём изменённые поля. Затем обсудим выбор контекста и порядок проверки окружения. Разделение файлов по каталогам само по себе не защищает от отправки результата в другой кластер: адрес назначения по-прежнему задаётся параметрами kubectl и kubeconfig."],
    terms: [['Основа конфигурации', 'Общие ресурсы, используемые несколькими вариантами.'], ['Наложение (overlay)', 'Набор изменений для конкретного окружения.'], ['kustomization.yaml', 'Описание ресурсов и преобразований Kustomize, не самостоятельный объект приложения.']],
    sections: [R("Основа и наложение", ['В k8s/overlays/dev/kustomization.yaml ссылка ../../lab.yaml ведёт к нашему полному общему файлу. Раздел replicas находит Deployment по имени и задаёт count: 1. Исходный lab.yaml не переписывается.', 'kubectl kustomize выводит итоговые документы. apply -k применяет результат, а не создаёт объект вида Kustomization в обычном Kubernetes. Не путайте этот локальный формат с пользовательскими ресурсами некоторых систем доставки, которые могут иметь похожее имя.']), R("Выбор окружения назначения", ['В нашем учебном примере разные варианты относятся к одному имени и пространству. Применение dev к текущему kubelab уменьшило бы число копий. Поэтому здесь выполняется только серверная проба. В рабочем проекте явно разделяют контексты, пространства имён и права доставки.', 'Значения образа, параметры и Secret должны иметь ясный источник. Не допускайте скрытого порядка ручных patch после автоматического применения. Сформированный результат полезно сохранять как проверяемый результат сборки без секретов и сравнивать перед доставкой.'])],
    steps: [S('Посмотрите результат наложения', `${cluster} kustomize k8s/overlays/dev`, 'Формируем четыре документа и ищем replicas: 1.', [['kustomize', 'Локально собрать описанную конфигурацию.']], 'В результате Deployment имеет одну копию; исходный файл на диске не изменился.'), S('Проверьте результат на сервере', `${cluster} apply --dry-run=server -k k8s/overlays/dev`, 'Проверяем сформированные объекты без сохранения.', [['-k', 'Путь к каталогу с kustomization.yaml.']], 'Документы проходят серверную пробу; живое число копий не меняется.'), S('Сверьте живой Deployment', `${k} get deployment kubelab -o yaml`, 'Отделяем просмотренное желаемое значение dev от текущего объекта кластера.', [['get deployment', 'Чтение существующего объекта.']], 'Текущее число копий соответствует прежнему состоянию, а не автоматически просмотренному count: 1.')],
    recap: ["Наложение Kustomize изменяет общую основу и формирует итоговый набор объектов.","Итоговую конфигурацию и контекст назначения проверяют до применения."], exercise: 'Что понадобится для второго варианта с тремя копиями? Отдельное наложение, ссылающееся на ту же основу и задающее count: 3; копировать весь Deployment не требуется.', question: 'Меняет ли kubectl kustomize работающий объект?', options: ['Нет, он формирует текст результата', 'Да, всегда', 'Да, если подключён кластер'], answer: 0, answerExplanation: 'Сохранение в кластере является отдельным действием.' }),
  L({ id: 'delivery', module: 'Эксплуатация и доставка', title: "Подготовка и доставка версии приложения", tag: 'Образы, проверки и GitOps',
    goal: 'Связать исходный код, проверенную сборку, идентичность образа и применение конфигурации.',
    introduction: ["Выпуск приложения связывает несколько самостоятельных результатов: исходный код, собранный образ, конфигурацию и состояние работающей службы. Чтобы установить причину ошибки или повторить выпуск, необходимо сохранить связь между этими результатами и проведёнными проверками.","Рассмотрим последовательность сборки, проверки и продвижения образа, затем сравним прямое применение конфигурации с получением изменений контроллером внутри кластера. Отдельное внимание уделим происхождению образа и условиям возврата. Успешное сохранение нового описания должно сопровождаться проверкой готовности и ответа приложения."],
    terms: [['Непрерывная интеграция', 'Автоматические проверки согласованного изменения исходников.'], ['Конвейер доставки', 'Последовательность получения исходников, проверок, сборки и доставки результата.'], ['GitOps', 'Подход, в котором согласованное желаемое состояние хранится в Git и приводится к нему контроллером.'], ['Происхождение сборки', 'Связь результата с исходниками, инструментами и выполненными проверками.']],
    sections: [R("Связь исходников и результата сборки", ['Зафиксируйте версию исходников и зависимостей. Выполните значимые проверки, соберите один результат и доставляйте именно его через окружения. Повторная сборка по тому же тегу в каждом окружении может дать разное содержимое.', 'Для рабочего реестра нужны ограниченные права публикации, сканирование известных уязвимостей, учёт происхождения и при необходимости проверка подписей. Подпись доказывает происхождение от выбранного ключа, а не отсутствие ошибок в программе. Сканирование также не доказывает полную безопасность.']), R("Способы доставки конфигурации", ['В прямой доставке программа сборки получает ограниченные права на целевое окружение. В GitOps она может публиковать образ и изменять описание в Git, а контроллер кластера применяет согласованное состояние. Эти варианты имеют разные границы доступа и отзыва.', 'Если контроллер следит за полем, ручной patch может быть возвращён к состоянию из Git. Для аварийной правки заранее определяют процедуру, последующее согласование и аудит. Секреты нельзя класть открытым текстом в публичную конфигурацию ради удобства доставки.']), R("Условия продвижения и возврата", ['Успешная сборка и принятый Deployment не доказывают исправность пользовательского сценария. Нужны проверки готовности, функциональная проверка и наблюдение после изменения. Укажите время наблюдения и пороги остановки.', 'Изменение схемы данных должно быть совместимо с порядком обновления и возврата программы. Если новая версия необратимо изменила данные, одного rollout undo недостаточно. Такие изменения требуют отдельного плана.'])],
    steps: [S('Соберите отдельный результат', 'minikube image build -t kubelab:delivery . -p kubelab', 'В локальном опыте используем отдельный тег. В рабочей системе привяжите обозначение к версии исходников и зафиксируйте digest.', [['-t kubelab:delivery', 'Учебная ссылка на новый результат, не перезаписывающая 1.0.']], 'Образ собран.'), S('Проверьте объект перед изменением', `${cluster} apply --dry-run=server -f k8s/lab.yaml`, 'Проверяем базовое описание на совместимость с сервером, не сохраняя его значения.', [['--dry-run=server', 'Серверная проба без применения.']], 'Документы приняты как dry run.'), S('Доставьте выбранный образ', `${k} set image deployment/kubelab web=kubelab:delivery`, 'Это ручной учебный шаг доставки. Он не записывает изменение в файл или Git.', [['set image', 'Обновить ссылку в шаблоне контейнера.']], 'Шаблон обновлён.'), S('Проверьте развёртывание', `${k} rollout status deployment/kubelab --timeout=120s`, 'Готовность — первая проверка после изменения, а не весь контроль выпуска.', [['--timeout=120s', 'Ограничить ожидание готовности.']], 'successfully rolled out.'), S('Верните образ для наблюдений', `${k} set image deployment/kubelab web=kubelab:observe`, 'Завершаем локальный опыт с заранее подготовленной версией.', [['kubelab:observe', 'Образ, собранный в занятии о метриках.']], 'Шаблон возвращён.'), S('Дождитесь возврата', `${k} rollout status deployment/kubelab --timeout=120s`, 'Проверяем готовность после возврата точно так же, как после доставки.', [['rollout status', 'Проверка текущего шаблона.']], 'successfully rolled out.')],
    recap: ["Выпуск связывает версию исходников, образ, конфигурацию и результаты проверок.","Применение объектов завершается проверкой фактической работы службы."], exercise: 'Напишите пять условий перед рабочим выпуском: идентичность образа, проверки, ограниченные права, подтверждение целевого окружения, план наблюдения и восстановления. Для каждого укажите проверяемое свидетельство.', question: 'Что произойдёт с ручной правкой поля, которым управляет GitOps-контроллер?', options: ['Она может быть возвращена к состоянию из Git', 'Она автоматически становится коммитом', 'Контроллер обязательно остановится'], answer: 0, answerExplanation: 'Источник желаемого состояния и владельцы полей должны быть согласованы.' }),
  L({ id: 'rollout-strategies', module: 'Эксплуатация и доставка', title: "Стратегии замены версии", tag: 'Стратегии выпуска', files: ['canary'],
    goal: 'Развернуть кандидата отдельно от основного трафика и понять требования к настоящей пробной доставке.',
    introduction: ["Разные стратегии выпуска по-разному распределяют риск и затраты. Последовательное обновление постепенно заменяет экземпляры. Схема blue-green сохраняет два набора и переключает доступ между ними. Canary сначала направляет ограниченную часть запросов новой версии и позволяет оценить её поведение до полного перехода.","На учебном примере рассмотрим переключение получателя Service и связанные с ним проверки. Затем обсудим условия для распределения трафика по весам. Доля Pod новой версии не определяет точную долю запросов: на результат влияют соединения, сеансы и используемый маршрутизатор."],
    terms: [['Canary', 'Ограниченный выпуск новой версии для части трафика с наблюдением и решением о продолжении.'], ['Blue-green', 'Два подготовленных варианта с управляемым переключением направления трафика.'], ['Предпросмотр', 'Отдельный доступ к кандидату до включения в основной маршрут.']],
    sections: [R("Переключение получателей Service", ['Имя Deployment kubelab-canary и метка app: kubelab-canary не совпадают с основным приложением. Service kubelab-preview выбирает только кандидата. Поэтому запуск кандидата не смешивает его с получателями исходного Service.', 'APP_VERSION здесь метка ответа программы, а не другой код. Для реального выпуска нужен отдельный проверенный образ. Такой приём позволяет безопасно изучить маршруты, не выдавая изменение строки за полноценное обновление программы.']), R("Распределение трафика по весам", ['Обычное добавление одной копии к нескольким старым не гарантирует точный процент пользовательских запросов. Соединения, сессии, способ балансировки и готовность влияют на распределение. Для управляемых долей нужен поддерживающий их шлюз, прокси или другая явно проверенная реализация.', 'До увеличения доли кандидата задайте сравнимые показатели, длительность наблюдения и критерий возврата. Учтите совместимость данных и сессий. Пустая новая версия без запросов может иметь ноль ошибок, но это не доказательство её пригодности.'])],
    steps: [apply('canary', 'Создаём изолированный предпросмотр без изменения селектора основного Service.', 'Deployment кандидата и Service предпросмотра созданы.'), S('Дождитесь кандидата', `${k} rollout status deployment/kubelab-canary --timeout=120s`, 'Проверяем готовность до открытия доступа.', [['deployment/kubelab-canary', 'Только экземпляры кандидата.']], 'successfully rolled out.'), S('Откройте предпросмотр', `${k} port-forward service/kubelab-preview 8082:80`, 'Откройте localhost:8082/api/runtime в реальном режиме, проверьте candidate и остановите туннель.', [['8082:80', 'Другой локальный порт для отдельного Service.']], 'Ответ кандидата. Это прямой предпросмотр, а не распределение основного трафика.'), S('Сверьте основной Service', `${k} get service kubelab -o yaml`, 'Найдите прежний selector app: kubelab.', [['selector', 'Условие выбора получателей основного маршрута.']], 'Основной Service не выбирает kubelab-canary.'), remove('canary', 'Удаляем кандидата и его отдельный Service. Основное приложение остаётся.')],
    recap: ["Выбор стратегии учитывает ёмкость, совместимость версий и порядок возврата.","Заданная доля трафика требует поддерживающего маршрутизатора и измерения фактических запросов."], exercise: 'У кандидата ноль ошибок, но всего один запрос. Достаточно ли этого для перевода всех пользователей? Нет: нужны достаточное наблюдение и согласованные критерии качества.', question: 'Почему основной Service не направляет запросы к кандидату?', options: ['Его selector не совпадает с меткой кандидата', 'Потому что имя содержит canary', 'Потому что порт локального туннеля 8082'], answer: 0, answerExplanation: 'Связь задаётся метками и селектором, а не смыслом имени.' }),
  L(operatorLesson),
  L({ id: 'platform', module: 'Расширение и платформа', title: "Требования к платформе приложений", tag: 'Практический проект', minutes: 75,
    goal: 'Объединить описания, доступ, данные, наблюдение и доставку в проверяемый план приложения.',
    introduction: ["Пользователю платформы нужен определённый результат: разместить приложение, получить доступ, увидеть состояние и устранить ошибку. Часть действий можно объединить в общий интерфейс, но при этом остаются вопросы ответственности, ограничений и сопровождения. Удобство определяется тем, насколько понятны и повторяемы эти операции.","Соберём изученные механизмы в проект небольшой платформы. Укажем входные параметры, создаваемые объекты, выдаваемые права и способы диагностики. Затем опишем проверку обычного запуска и отказов. В итоговом проекте важно показать не только успешное создание приложения, но и порядок его изменения, восстановления и удаления."],
    terms: [['Контракт платформы', 'Какие возможности получает команда, что она обязана задать и кто отвечает за результат.'], ['Самообслуживание', 'Получение согласованных ресурсов по понятным правилам без ручного вмешательства администратора в каждый запрос.'], ['Абстракция', 'Сокрытие части деталей за понятным интерфейсом при сохранении нужного контроля и возможности диагностики.']],
    sections: [R("Возможности интерфейса платформы", ['Команде могут быть нужны образ, настройки, маршрут, данные, журналы, метрики и ограниченные права. Часть можно выдавать шаблоном, пакетом или собственным ресурсом. Но пользователь должен понимать, где посмотреть состояние и что означает отказ.', 'Не скрывайте обязательные решения за случайными значениями по умолчанию. Если платформа сама выбирает лимиты, правила доступа или способ хранения, объясните основания и путь изменения. Обратная связь и понятные ошибки важнее количества кнопок.']), R("Состав итогового проекта", ['В своей копии рабочей папки подготовьте повторяемое описание приложения, отдельные несекретные настройки, безопасный способ передачи учебного Secret, запросы и лимиты, готовность и завершение процесса. Укажите, какие данные должны пережить замену Pod и как они восстанавливаются.', 'Добавьте правила доступа и сети, перечень нужных дополнений и версий. Составьте проверки до выпуска, после выпуска и при возврате. Для наблюдения определите хотя бы один показатель качества пользователя и связь запроса с журналом.', 'Для каждого пункта приложите свидетельство: полный файл, команду, ожидаемый результат и фактическое наблюдение. Если часть проверена только в тренажёре или на уровне конфигурации, так и напишите. Не подменяйте неизвестность успешным сообщением симулятора.']), R("Проверка работы и отказов", ['Повторное применение не должно создавать лишние независимые объекты. Замена Pod сохраняет только те данные, для которых предусмотрено хранилище. Неверный образ должен обнаруживаться понятной диагностикой, а возврат подтверждаться фактической готовностью.', 'Проверьте недостаточные права отдельной учётной записи и действие сетевого правила запросом. Продумайте восстановление в другом окружении, а не только перезапуск текущего. Опишите оставшиеся ограничения: один узел, локальный диск, отсутствующие внешний маршрут и долговременный сбор наблюдений.', 'Последняя уборка удаляет только объекты своих опытов. Для общих хранилищ, пространств имён и профилей нужно точное понимание содержимого. Если вы сохранили важные изменения, не запускайте команды удаления из другого примера.'])],
    steps: [S('Проверьте приложение', `${k} rollout status deployment/kubelab --timeout=120s`, 'Начинаем итоговый отчёт с наблюдаемого состояния.', [['rollout status', 'Проверить текущий шаблон Deployment.']], 'successfully rolled out.'), S('Зафиксируйте объекты проекта', `${k} get deployments,services,configmaps,pvc`, 'Сверьте оставшиеся объекты со своим ожидаемым списком. Пустые дополнительные заявки после очистки опытов допустимы.', [['Перечень через запятую', 'Запросить несколько видов объектов одним чтением.']], 'Основные объекты приложения существуют; временные объекты завершённых опытов убраны.'), S('Верните исходную ссылку на образ', `${k} set image deployment/kubelab web=kubelab:1.0`, 'Завершаем общий учебный стенд на первоначальном образе. Это не удаляет ваши копии файлов.', [['web=kubelab:1.0', 'Вернуть исходную ссылку контейнера.']], 'Шаблон обновлён.'), S('Подтвердите итоговое состояние', `${k} rollout status deployment/kubelab --timeout=120s`, 'После возврата снова нужна готовность, а не только ответ команды изменения.', [['rollout status', 'Проверка после последнего изменения.']], 'Приложение готово. Результат итогового задания оформляется отдельно по критериям выше.')],
    recap: ["Интерфейс платформы описывает результат, ограничения и обязанности сопровождающих.","Проверка платформы включает запуск, изменение, диагностику отказа и завершение работы."], exercise: 'Дайте своему проекту другому человеку: сможет ли он по вашим файлам повторить установку, объяснить команды, найти намеренную ошибку и выполнить восстановление? Исправьте все места, где ему пришлось угадывать.', question: 'Что лучше всего доказывает готовность итогового проекта?', options: ['Повторяемые файлы и наблюдаемые проверки по согласованным критериям', 'Только число установленных компонентов', 'Только отметка о прочтении уроков'], answer: 0, answerExplanation: 'Полезный результат должен быть воспроизводим и проверяем, с явно указанными границами.' })
);
advancedLessons.push(
  L({ id: 'dns', module: 'Сеть приложений', title: "Имена служб и DNS", tag: 'Служба имён и Service', files: ['client'],
    goal: 'Проверить разрешение имени Service из Pod и отделить его от доступа с Windows.',
    introduction: ["Приложениям удобно обращаться к соседним службам по именам, а не сохранять изменяющиеся адреса Pod. Kubernetes публикует DNS-имена Service, область которых зависит от пространства имён и домена кластера. Разрешение имени является первым этапом соединения, после которого ещё необходимо установить связь и получить ответ.","Проверим короткое и полное имя учебного Service из клиентского Pod. Затем сопоставим DNS-результат со списком получателей и состоянием приложения. Такой порядок позволяет различить ошибку имени, отсутствие готовых конечных точек, запрет сети и ошибку уже работающего сервера."],
    terms: [['Служба доменных имён (DNS)', 'Сопоставляет имя с адресом; внутри Kubernetes обслуживает в том числе имена Service.'], ['Полное имя Service', 'Обычно имеет вид имя.пространство.svc.домен-кластера.'], ['CoreDNS', 'Распространённая реализация службы имён в Kubernetes.'], ['EndpointSlice', 'Объект с адресами получателей Service; разрешение имени ещё не доказывает готовность этих получателей.']],
    sections: [R("Разрешение имени и соединение", ['В пространстве kubelab короткое имя kubelab обычно разрешается в Service того же пространства. Полное имя kubelab.kubelab.svc.cluster.local делает область явной для стандартного домена Minikube. В другом кластере домен может отличаться.', 'У обычного ClusterIP имя указывает на виртуальный адрес Service. У headless Service результаты связаны с адресами Pod. Успешный поиск имени ещё не проверяет порт, наличие готовых получателей и правила сети. Проверять эти этапы нужно последовательно.']), R("Диагностика обращения к службе", ['Ошибка ENOTFOUND относится к разрешению имени: проверьте написание, пространство имён и службу DNS. Отказ соединения или таймаут после получения адреса относятся к другому этапу: проверьте Service, получателей, порт и политики.', 'Наш клиент использует fetch с ограничением времени три секунды. Программа выводит только имя обслужившего Pod. Она не печатает заголовки авторизации или конфиденциальные настройки. После опыта клиентский Pod можно удалить без изменения веб-приложения.'])],
    steps: [apply('client', 'Создаём независимого клиента для запросов из сети кластера.', 'Pod kubelab-client создан.'), S('Найдите адрес по полному имени', `${k} exec pod/kubelab-client -- node -e "require('node:dns').lookup('kubelab.kubelab.svc.cluster.local',(e,a)=>{if(e){console.error(e.code);process.exitCode=1}else console.log(a)})"`, 'Программа выполняется в клиентском Pod, поэтому использует настройки DNS кластера.', [['exec pod/kubelab-client --', 'Запустить следующую программу внутри выбранного клиента.'], ['lookup', 'Проверить разрешение имени средствами Node.js.']], 'Получен внутренний адрес Service.', 'Если контейнер ещё не запущен, подождите его Ready через get pods и повторите.'), S('Проверьте HTTP-запрос', `${k} exec pod/kubelab-client -- node -e "fetch('http://kubelab/api/runtime',{signal:AbortSignal.timeout(3000)}).then(r=>r.json()).then(x=>console.log(x.pod)).catch(e=>{console.error(e.name);process.exitCode=1})"`, 'Отдельно проверяем, что за найденным именем есть доступное приложение.', [['http://kubelab', 'Service kubelab на его порту 80.'], ['AbortSignal.timeout(3000)', 'Ограничить ожидание запроса тремя секундами.']], 'Имя одного из готовых Pod веб-приложения.'), remove('client', 'Удаляем только клиентский Pod.')],
    recap: ["DNS связывает имя Service с адресом, предназначенным для доступа к нему.","Успешное разрешение имени не подтверждает соединение и работоспособность получателя."], exercise: 'Почему открытие cluster.local в браузере Windows может не работать при исправном приложении? Служба имён и внутренние адреса кластера не обязаны быть доступны вашему компьютеру напрямую.', question: 'Что доказывает успешный DNS-поиск?', options: ['Что имя удалось сопоставить с адресом', 'Что все контейнеры готовы', 'Что пароль приложения правильный'], answer: 0, answerExplanation: 'После поиска имени отдельно проверяются соединение, порт и протокол приложения.' }),
  L({ id: 'cni', module: 'Сеть приложений', title: "Сеть Pod и интерфейс CNI", tag: 'Адреса и маршруты',
    goal: 'Отличить сеть Pod от Service и понять роль подключаемого сетевого компонента.',
    introduction: ["Сеть Kubernetes должна обеспечить связь между Pod и предоставить условия для работы сетевых правил. На практике эти возможности реализуются сетевыми компонентами, которые подключаются к окружению узла через CNI. Выбор реализации влияет на выдачу адресов, передачу пакетов, политики и доступные средства диагностики.","Рассмотрим различия между связностью и ограничением доступа, затем перейдём к маршрутизации, инкапсуляции и размеру пакета. Отдельно обсудим шифрование и два семейства адресов. Просмотр установленной конфигурации помогает определить устройство стенда; замена сетевого компонента требует самостоятельной подготовки и проверки."],
    terms: [['Интерфейс управления сетью контейнеров (CNI)', 'Правила подключения контейнерного окружения к сети через плагины.'], ['Сеть Pod', 'Адресация и связь экземпляров приложений.'], ['Виртуальный адрес Service', 'Стабильная точка входа, сопоставляемая с подходящими получателями.'], ['Инкапсуляция', 'Передача одного сетевого пакета внутри другого для доставки через основную сеть.']],
    sections: [R("Связность и ограничение доступа", ['Создать маршрут между адресами Pod — одна задача. Направить запрос виртуального адреса Service к готовому Pod — другая. В конкретной реализации это могут выполнять разные компоненты или один сетевой проект с несколькими функциями.', 'В многосерверной сети применяют маршрутизацию, наложенные сети или их сочетания. Выбор влияет на требования к основной сети, размер пакета, задержки, наблюдение и правила доступа. Название CNI само по себе не гарантирует поддержку NetworkPolicy.']), R("Шифрование, IPv4 и IPv6", ['Наличие внутреннего адреса не означает шифрование трафика. Защиту между узлами, защиту HTTP и проверку личности приложения нужно проектировать отдельно. Механизм сетевого туннеля тоже не обязательно шифрует содержимое.', 'Двойная адресация IPv4/IPv6 требует поддержки всей цепочки: узлов, плагина, Service, DNS и внешних клиентов. Нельзя получить полноценную двухстековую систему только добавлением второго адреса в манифест. Проверки должны охватывать оба семейства адресов.']), R("Условия замены сетевого компонента", ['Проверьте совместимость версий, способ выдачи адресов, поддержку политик, требования к ядру и процесс обновления. Нужны отдельный стенд, наблюдение и план отката. Замена сети текущего кластера может нарушить все приложения сразу.', 'В следующем опыте с политиками используем отдельный профиль с поддерживающим их плагином. Текущий профиль не переустанавливаем. Это позволяет отделить проверку правила от риска изменения всей существующей сети.'])],
    steps: [S('Сравните адреса Pod', `${k} get pods -o wide`, 'Прочитайте IP и NODE. На нашем стенде несколько адресов принадлежат Pod одного узла.', [['-o wide', 'Дополнительные поля списка Pod.']], 'У разных копий разные адреса, а узел один.'), S('Сравните адрес Service', `${k} get service kubelab -o yaml`, 'Найдите clusterIP, selector и targetPort.', [['get service kubelab -o yaml', 'Прочитать описание Service полностью.']], 'Адрес ClusterIP отличается от адресов отдельных Pod.'), S('Посмотрите сетевые службы', `${cluster} -n kube-system get daemonsets`, 'DaemonSet часто используется для служб на каждом узле. Состав зависит от выбранного плагина.', [['get daemonsets', 'Показать контроллеры служб, размещаемых на узлах.']], 'Запишите доступные имена. Отсутствие конкретного имени из чужого примера не является само по себе ошибкой.')],
    recap: ["Связность Pod и применение сетевых ограничений являются отдельными свойствами реализации.","Пулы адресов, маршруты и MTU необходимо согласовать с сетью узлов."], exercise: 'На одном узле всё работает, а между узлами запросы пропадают. Какие новые части появились? Основная сеть, маршруты или туннели между узлами, их фильтры и допустимый размер пакета.', question: 'Гарантирует ли любой сетевой плагин применение NetworkPolicy?', options: ['Нет, поддержку и фактическое действие нужно проверить', 'Да, достаточно создать объект', 'Да, если адрес начинается с 10'], answer: 0, answerExplanation: 'Сохранённый объект политики может существовать без реализации её правил сетью.' }),
  L({ id: 'ingress', module: 'Сеть приложений', title: "Входящие HTTP-запросы и Ingress", tag: 'Ingress и TLS', files: ['ingress'], practiceKind: 'Проверка конфигурации',
    goal: 'Прочитать правило маршрута и проверить его на сервере, понимая необходимость отдельного контроллера.',
    before: 'Нужны основной кластер и Service kubelab. Для проверки описания контроллер Ingress не обязателен. Для настоящего внешнего HTTP-доступа нужен совместимый контроллер и путь от Windows до него. Стандартное дополнение ingress Minikube с Docker-драйвером на Windows не поддерживается; включать его как гарантированное решение мы не предлагаем.',
    introduction: ["Service предоставляет доступ к экземплярам приложения, а Ingress описывает выбор HTTP-службы по имени узла и пути запроса. Сам объект Ingress не обрабатывает соединения. Для применения его правил требуется контроллер, который получает описания из Kubernetes и настраивает обработку входящего трафика.","Разберём имя узла, путь и ссылку на Service в полном манифесте. Затем определим, что ещё нужно клиенту: доступный адрес входа, правильное DNS-имя и, при необходимости, сертификат. Сохранение Ingress подтверждает приём описания; результат публикации проверяется настоящим HTTP-запросом через настроенный вход."],
    terms: [['Ingress', 'Описание правил внешнего HTTP-маршрута к Service.'], ['IngressClass', 'Указывает, какой контроллер должен обслуживать правила этого класса.'], ['TLS', 'Защита соединения с проверкой сертификата сервера; в браузере обычно используется через HTTPS.'], ['Завершение TLS', 'Место, где принимается защищённое соединение; дальше маршрут может быть устроен отдельно.']],
    sections: [R("Структура маршрута Ingress", ['host: kubelab.test выбирает имя HTTP-запроса, path: / с pathType: Prefix задаёт путь. backend.service.name указывает существующий Service kubelab, а number: 80 — порт именно Service. Это не порт контейнера 3000 и не произвольный порт Windows.', 'ingressClassName: nginx — имя класса, а не команда установки nginx. Если такого класса и обслуживающего контроллера нет, правило не создаст работающего внешнего маршрута. Статус ADDRESS также зависит от контроллера и окружения.']), R("Проверка входящего запроса", ['Клиент должен разрешить kubelab.test в доступный адрес контроллера, соединиться с его портом и отправить нужное имя Host. Подмена DNS-записи сама не создаёт контроллер. port-forward к приложению тоже не проверяет правило Ingress: он обходит этот маршрут.', 'Для HTTPS нужен сертификат на используемое имя и соответствующий закрытый ключ в защищённом Secret либо поддерживаемое внешнее хранилище. Затем в Ingress добавляют tls с hosts и secretName. Проверка доверия клиента, срока действия и автоматического обновления остаётся отдельной задачей. Закрытый ключ не публикуют вместе с примером.', 'В новых платформах также используют Gateway API с явным разделением объектов шлюза и маршрутов. Перед выбором сравните поддержку конкретного контроллера и ваших требований. Формат маршрута и установленная реализация должны соответствовать друг другу.'])],
    steps: [S('Проверьте установленные классы', `${cluster} get ingressclass`, 'Сначала выясняем, есть ли в окружении объявленные классы.', [['get ingressclass', 'Список классов Ingress всего кластера.']], 'Список может быть пустым. В нашем исходном Minikube это допустимо и означает, что готовый внешний маршрут не обещан.'), S('Проверьте документ без сохранения', `${cluster} apply --dry-run=server -f k8s/advanced/ingress.yaml`, 'Проверяем схему и правила допуска для документа. Сам контроллер этой командой не устанавливается.', [['--dry-run=server', 'Проверить на сервере без создания Ingress.']], 'Документ принят как dry run. Это не проверка доступности kubelab.test.'), S('Сверьте внутреннего получателя', `${k} get endpointslices -l kubernetes.io/service-name=kubelab`, 'Даже с готовым контроллером он не сможет передать запрос отсутствующим или неготовым получателям.', [['-l kubernetes.io/service-name=kubelab', 'Выбрать получателей указанного Service.']], 'Найдены адреса приложения на порту 3000.')],
    recap: ["Ingress описывает маршрут, а установленный контроллер обеспечивает его обработку.","Публикация проверяется запросом с правильными адресом, именем и путём."], exercise: 'Правило принято, но kubelab.test не открывается. Перечислите проверки по порядку: разрешение имени, доступность контроллера, класс, правило Host/пути, Service, готовые получатели.', question: 'Устанавливает ли apply Ingress сам контроллер?', options: ['Нет, это отдельный компонент', 'Да, из поля ingressClassName', 'Да, из поля host'], answer: 0, answerExplanation: 'Описание маршрута исполняется подготовленным контроллером.' }),
  L({ id: 'network-policy', module: 'Сеть приложений', title: "Ограничение сетевого доступа", tag: 'NetworkPolicy', context: 'kubelab-policy', files: ['client', 'deny', 'allow'], minutes: 70,
    goal: 'Подтвердить исходное соединение, действие запрета и точечное разрешение в отдельной сети.',
    before: 'Нужны дополнительные скачивания и совместимость Docker, Minikube и Calico. Опыт использует отдельный профиль kubelab-policy. Если там уже есть ваши данные, не выполняйте создание и удаление без выбора другого учебного имени. Основной профиль временно остановим, чтобы освободить память. Не переносите запрет сети в рабочий кластер.',
    introduction: ["По мере появления нескольких приложений возникает необходимость ограничивать связи между ними. NetworkPolicy задаёт разрешённые источники и назначения для выбранных Pod. Применять такие правила должен установленный сетевой компонент; наличие объекта в API само по себе этого не подтверждает.","Сначала создадим правило, ограничивающее вход к учебному серверу, а затем разрешим обращение выбранному клиенту. Проверки проведём из клиентского Pod: до ограничения, после запрета и после разрешения. Это позволит связать наблюдаемый результат с изменением правила и отличить сетевой отказ от неисправности самого приложения."],
    terms: [['NetworkPolicy', 'Разрешённые направления соединений для выбранных Pod, если сетевой компонент исполняет такие правила.'], ['Изоляция входящих соединений', 'Для выбранных Pod действуют перечисленные разрешения входящего трафика.'], ['Селектор получателя', 'podSelector у самой политики определяет защищаемые Pod.'], ['Селектор отправителя', 'podSelector внутри from выбирает допустимые источники в том же пространстве имён, если не указан другой выбор пространств.']],
    sections: [R("Выбор Pod и разрешённые соединения", ['В deny.yaml ingress: [] не разрешает ни одного входящего соединения к выбранным Pod. В allow.yaml объект имеет то же имя: применение заменяет его желаемые правила и разрешает порт контейнера 3000 только отправителям с access: web.', 'Политики суммируют разрешения. Если другая политика разрешила соединение, более узкий объект не отменит это разрешение. Здесь выбран чистый учебный профиль, чтобы не перепутать действие правила с существующими разрешениями. Исходящие соединения и DNS мы этим правилом не ограничиваем.']), R("Последовательность сетевой проверки", ['До запрета запрос клиента должен пройти. Иначе последующий таймаут ничего не доказывает о политике. После запрета дождитесь применения правил сетью и повторите запрос. При точечном разрешении проверьте и метку клиента, и порт получателя.', 'В реальном окружении политика может применяться с небольшой задержкой. Повторяйте проверку после ожидания, а не меняйте случайные поля. Если после запрета запросы стабильно проходят, сначала проверьте поддержку и исполнение политик, совпадение селектора и другие разрешающие правила.'])],
    steps: [S('Освободите ресурсы основного профиля', 'minikube stop -p kubelab', 'Останавливаем кластер, сохраняя его состояние. Для курса с политиками будет создано отдельное окружение.', [['stop', 'Остановить профиль без удаления его данных.']], 'Основной профиль остановлен.'), S('Создайте профиль с поддержкой политик', 'minikube start -p kubelab-policy --driver=docker --cni=calico --cpus=2 --memory=3072', 'Новый профиль получает отдельную сеть. Первый запуск может занять несколько минут.', [['--cni=calico', 'Выбрать сетевой компонент с поддержкой NetworkPolicy.'], ['-p kubelab-policy', 'Отдельное имя опыта.']], 'Кластер запущен. Если компонент не совместим с вашим окружением, остановитесь на подготовке; без него действие правил не доказано.'), S('Соберите образ в новом профиле', 'minikube image build -t kubelab:1.0 . -p kubelab-policy', 'Локальный образ основного профиля не переносится автоматически.', [['-p kubelab-policy', 'Собрать образ на узле нового профиля.']], 'Образ собран.'), S('Создайте сервер', 'kubectl --context kubelab-policy apply -f k8s/lab.yaml', 'В отдельном кластере применяем знакомый полный файл.', [['--context kubelab-policy', 'Отправить описание только в кластер опыта.']], 'Пространство имён, настройки, Deployment и Service созданы.'), S('Дождитесь сервера', 'kubectl --context kubelab-policy -n kubelab rollout status deployment/kubelab --timeout=180s', 'До испытания сети приложение должно быть готово.', [['rollout status', 'Дождаться готовности учебного сервера.']], 'successfully rolled out.'), S('Создайте клиента', 'kubectl --context kubelab-policy apply -f k8s/advanced/client.yaml', 'Клиент будет отправлять запрос из сети нового кластера.', [['apply -f', 'Создать отдельный клиентский Pod.']], 'Pod создан.'), S('Разрешите клиенту получить нужную метку', 'kubectl --context kubelab-policy -n kubelab label pod kubelab-client access=web --overwrite', 'Метка пока ничего не разрешает сама: правило появится позже.', [['access=web', 'Признак разрешённого отправителя в нашем примере.']], 'Pod помечен.'), S('Проверьте исходное соединение', 'kubectl --context kubelab-policy -n kubelab exec pod/kubelab-client -- node -e "fetch(\'http://kubelab/healthz\',{signal:AbortSignal.timeout(3000)}).then(r=>console.log(r.status)).catch(e=>{console.error(e.name);process.exitCode=1})"', 'Проверяем исходную работоспособность до запрета.', [['fetch', 'HTTP-запрос из клиентского Pod.']], '200. Если клиент ещё запускается, дождитесь его готовности и повторите.'), S('Запретите входящие соединения', 'kubectl --context kubelab-policy apply -f k8s/advanced/deny.yaml', 'Изолируем только выбранные серверные Pod.', [['ingress: []', 'В этом объекте нет разрешённых входящих соединений.']], 'NetworkPolicy создана.'), S('Подтвердите действие запрета', 'kubectl --context kubelab-policy -n kubelab exec pod/kubelab-client -- node -e "fetch(\'http://kubelab/healthz\',{signal:AbortSignal.timeout(3000)}).then(r=>console.log(r.status)).catch(e=>{console.error(e.name);process.exitCode=1})"', 'Повторяем тот же запрос. Изменилось правило сети, а не имя или порт приложения.', [['timeout(3000)', 'Запрос завершится по таймауту вместо бесконечного ожидания.']], 'После применения политики ожидаются ошибка запроса и код 1. Это ожидаемый результат данного шага.', 'Если запрос проходит, проверьте исполнение политик и другие разрешения; не объявляйте опыт успешным.', 1), S('Добавьте узкое разрешение', 'kubectl --context kubelab-policy apply -f k8s/advanced/allow.yaml', 'Тот же объект теперь разрешает клиента с access: web на порт 3000.', [['from.podSelector', 'Выбрать разрешённых отправителей по метке.']], 'NetworkPolicy обновлена.'), S('Проверьте восстановление соединения', 'kubectl --context kubelab-policy -n kubelab exec pod/kubelab-client -- node -e "fetch(\'http://kubelab/healthz\',{signal:AbortSignal.timeout(3000)}).then(r=>console.log(r.status)).catch(e=>{console.error(e.name);process.exitCode=1})"', 'Проверяем изменение поведения фактическим запросом.', [['r.status', 'Вывести полученный HTTP-статус.']], 'После применения разрешения — 200.'), S('Удалите только профиль опыта', 'minikube delete -p kubelab-policy', 'Это намеренно удаляет кластер опыта и все его данные. Основной профиль kubelab не выбран.', [['delete -p kubelab-policy', 'Удалить отдельный учебный профиль.']], 'Профиль опыта удалён.'), S('Верните основной кластер', 'minikube start -p kubelab', 'Возвращаем сохранённое окружение для следующих уроков.', [['start -p kubelab', 'Запустить ранее остановленный основной профиль.']], 'Основной кластер снова работает.')],
    recap: ["NetworkPolicy выбирает Pod и определяет разрешённые направления связи.","Действие правила проверяется разрешёнными и запрещёнными соединениями при поддерживающей его сетевой реализации."], exercise: 'Почему нельзя проверять эту политику через port-forward вместо клиента? Перенаправление проходит по другому пути и не является проверкой обычного соединения между Pod.', question: 'Как доказать действие политики?', options: ['Сравнить фактический запрос до запрета, после запрета и после разрешения', 'Получить только сообщение configured', 'Убедиться, что файл существует'], answer: 0, answerExplanation: 'Нужна проверка поведения сети, а не только существования описания.' })
);
advancedLessons.push(
  L({ id: 'tenants', module: 'Безопасность и разделение', title: "Пространства имён, квоты и общие ресурсы", tag: 'Квоты и значения по умолчанию', files: ['tenant'], namespace: 'kubelab-team',
    goal: 'Создать отдельную область команды и прочитать её бюджет ресурсов.',
    introduction: ["Общий кластер может обслуживать несколько команд. Пространство имён позволяет разделить их объекты, однако вычислительные ресурсы и часть служебных компонентов остаются общими. Чтобы одна команда не израсходовала доступную ёмкость, требуются ограничения как на отдельные контейнеры, так и на суммарное потребление проекта.","Создадим отдельное учебное пространство и рассмотрим LimitRange и ResourceQuota. Первый объект задаёт стандартные значения и ограничения для контейнеров, второй — общий бюджет пространства. Затем обсудим, какие задачи остаются за RBAC, сетевыми правилами и более сильным разделением окружений."],
    terms: [['ResourceQuota', 'Ограничивает суммарные запросы, лимиты или количество объектов пространства имён.'], ['LimitRange', 'Задаёт ограничения и значения по умолчанию для отдельных контейнеров или объектов.'], ['Мультитенантность', 'Совместное использование платформы несколькими независимыми командами или клиентами.']],
    sections: [R("Индивидуальные и суммарные ограничения", ['В квоте pods: 5 ограничивает число Pod. requests.cpu: 500m и requests.memory: 512Mi ограничивают сумму запросов, а limits.cpu и limits.memory — сумму заявленных ограничений. Это разные суммы, а не одна общая колонка потребления.', 'LimitRange подставляет отсутствующие запросы 25m/32Mi и ограничения 200m/128Mi. При проверке квоты учитываются фактически получившиеся значения. Поэтому «в моём YAML не было memory» не означает, что контейнер вообще не учитывается в бюджете.']), R("Область пространства имён", ['Квота не гарантирует время ответа, справедливое распределение процессора в каждый момент или изоляцию узла от вредоносного процесса. Права доступа, сетевые политики и настройки безопасности решают другие задачи.', 'Для команд с разной степенью доверия может понадобиться отдельный кластер. Учитывайте доступ к общим компонентам, возможность чтения сведений о других клиентах и последствия ошибки администратора. Выбор разделения должен вытекать из требований, а не из желания сэкономить одно имя кластера.'])],
    steps: [apply('tenant', 'Создаём отдельное пространство имён, его квоту и значения контейнеров по умолчанию.', 'Namespace kubelab-team, ResourceQuota и LimitRange созданы.'), S('Прочитайте бюджет', `${cluster} -n kubelab-team describe resourcequota team-budget`, 'Сравните Hard и Used. Это границы и уже учтённые объекты, а не график фактической нагрузки.', [['describe resourcequota', 'Показать расход каждого ограниченного вида ресурсов.']], 'На пустом стенде Used близко к нулю; Hard соответствует файлу.'), S('Проверьте правила контейнера', `${cluster} -n kubelab-team get limitrange container-defaults -o yaml`, 'Прочитайте defaultRequest и default отдельно.', [['defaultRequest', 'Запрос при отсутствии явного значения.'], ['default', 'Лимит при отсутствии явного значения.']], 'Видны разные значения запроса и лимита.'), remove('tenant', 'Это удалит весь учебный Namespace kubelab-team и его содержимое. Основное пространство kubelab не выбрано.')],
    recap: ["LimitRange задаёт ограничения отдельных объектов, ResourceQuota — общий бюджет пространства имён.","Namespace необходимо дополнять управлением правами, сетью и ресурсами."], exercise: 'Пять контейнеров по умолчанию имеют лимит 128Mi. Поместятся ли они в limits.memory: 1Gi? Сумма 640Mi помещается; дополнительно нужно проверить остальные ограничения и число Pod.', question: 'Какой объект ограничивает суммарное число Pod команды?', options: ['ResourceQuota', 'Service', 'ConfigMap'], answer: 0, answerExplanation: 'Квота относится к общей области, а не только к одному контейнеру.' }),
  L({ id: 'pod-security', module: 'Безопасность и разделение', title: "Ограничения полномочий контейнера", tag: 'Безопасность Pod', files: ['restricted', 'security-check'], namespace: 'kubelab-security',
    goal: 'Проверить ограниченный Pod в отдельном пространстве с правилами restricted.',
    introduction: ["Контейнеру веб-приложения обычно не нужны права администратора узла. Он может работать от отдельного пользователя, с ограниченным набором возможностей и файловой системой только для чтения. Такие настройки уменьшают доступные процессу действия и требуют заранее определить каталоги, в которые приложение вправе записывать данные.","Рассмотрим securityContext нашего примера и выясним назначение каждого поля. Затем отделим настройки контейнера от правил, проверяющих допустимость Pod при его создании. Проверка будет полезной лишь в том случае, если её область действия определена явно, а приложение действительно способно работать с выбранными ограничениями."],
    terms: [['Pod Security Admission', 'Встроенная проверка Pod по выбранному стандарту безопасности.'], ['restricted', 'Строгий набор стандартных ограничений для обычных приложений.'], ['seccomp', 'Ограничение доступных процессу системных вызовов Linux.'], ['Дополнительные возможности Linux (capabilities)', 'Отдельные привилегированные действия, которые можно убрать или добавить процессу.']],
    sections: [R("Параметры безопасности контейнера", ['runAsNonRoot: true требует запуск без root. UID 1000 определяет пользователя. allowPrivilegeEscalation: false запрещает получение дополнительных привилегий обычным путём повышения. capabilities.drop: ALL убирает дополнительные возможности. seccompProfile RuntimeDefault включает стандартный профиль среды выполнения.', 'readOnlyRootFilesystem уменьшает возможность изменения файлов образа во время работы. Оно не запрещает запись во все отдельно подключённые тома. Если программе нужен временный каталог, его следует спроектировать явно с подходящими правами и размером.']), R("Область действия политики", ['Метки Namespace выбирают режим enforce и набор restricted. enforce отклоняет неподходящие новые Pod; режимы warn и audit нужны для предупреждения и наблюдения при подготовке перехода. Применение метки не превращает уже работающий процесс автоматически в безопасный.', 'В этом локальном опыте версия правил latest следует версии сервера. В рабочем проекте фиксируют согласованную версию и проверяют изменения перед обновлением. Устаревшие PodSecurityPolicy в современных кластерах не используются: правила допуска и актуальные стандарты нужно выбирать по версии сервера.'])],
    steps: [apply('restricted', 'Создаём только отдельное пространство имён с ограничениями.', 'Namespace kubelab-security создан.'), S('Проверьте Pod на сервере', `${cluster} apply --dry-run=server -f k8s/advanced/security-check.yaml`, 'Серверная проба проверит схему и правила безопасности до запуска.', [['--dry-run=server', 'Проверить без сохранения Pod.']], 'Pod проходит проверку restricted без нарушения правил.'), apply('security-check', 'Теперь создаём проверенный учебный Pod в отдельном пространстве.', 'Pod kubelab-safe создан.'), S('Проверьте состояние', `${cluster} -n kubelab-security get pods`, 'Серверный допуск и запуск — разные этапы. Проверяем фактический запуск из уже собранного образа.', [['-n kubelab-security', 'Область только этого опыта.']], 'После запуска Pod Running и готов.'), remove('security-check', 'Удаляем учебный процесс.'), remove('restricted', 'Удаляем отдельное пространство безопасности с его правилами.')],
    recap: ["SecurityContext задаёт условия запуска и полномочия процесса контейнера.","Политика допуска и фактический запуск с ограничениями проверяются по отдельности."], exercise: 'Почему readOnlyRootFilesystem не заменяет ограничение доступа к Secret? Оно ограничивает запись в файловую систему образа, а не разрешения на чтение объектов Kubernetes.', question: 'Когда enforce проверяет создаваемый Pod?', options: ['До сохранения и запуска неподходящей конфигурации', 'Только после первого взлома', 'Только при удалении'], answer: 0, answerExplanation: 'Проверка допуска может отклонить конфигурацию до её запуска.' }),
  L({ id: 'secret-rotation', module: 'Безопасность и разделение', title: "Обновление конфиденциальных настроек", tag: 'Ротация и внешнее хранение', files: ['rotation'],
    goal: 'Разделить изменение Secret, обновление процесса и отзыв прежнего значения.',
    introduction: ["Конфиденциальное значение со временем приходится заменять: например, истёк срок ключа или изменились данные доступа к службе. Для приложения важен не только момент записи нового Secret, но и момент, когда работающий процесс начнёт использовать новое значение. Эти события могут не совпадать.","Сравним Secret в API, настройку созданного контейнера и поведение его процесса. В примере значение передаётся через окружение, поэтому для получения новой версии понадобится замена Pod. Далее рассмотрим порядок реальной смены: временную совместимость, проверку новых потребителей и отзыв прежнего значения."],
    terms: [['Ротация', 'Контролируемая замена учётных данных с проверкой потребителей и отзывом старого доступа.'], ['Внешнее хранилище секретов', 'Отдельная система управления конфиденциальными значениями и их жизненным циклом.'], ['Краткоживущие учётные данные', 'Данные доступа с ограниченным сроком, требующие обновления потребителем.']],
    sections: [R("Хранение, доставка и использование значения", ['Есть значение в источнике, значение в объекте Secret и значение, полученное процессом. При передаче через переменную окружения третье состояние не меняется после patch. Для получения нового значения нужен новый контейнер.', 'Для файловых проекций изменение доставляется иначе и не обязательно мгновенно. Программа должна перечитать файл, а подключение через subPath имеет отдельные ограничения обновления. Не считайте любой способ передачи Secret автоматически динамическим.']), R("Порядок смены конфиденциальных данных", ['Сначала готовят новое значение в системе, которая его принимает. Затем доставляют его потребителям, проверяют успешные операции и только после этого отзывают прежнее. Если внешняя система допускает одновременную работу двух версий, переход проще выполнить без перерыва.', 'Внешний менеджер может выдавать краткоживущие данные или синхронизировать их через специальный компонент. Это добавляет зависимость: нужны доверие, ограниченные права, аудит, доступность и процедура продления. Не храните долгоживущий административный ключ рядом с приложением только ради подключения к менеджеру.'])],
    steps: [apply('rotation', 'Создаём выдуманный Secret и отдельный Deployment-потребитель.', 'Оба объекта созданы.'), S('Дождитесь потребителя', `${k} rollout status deployment/kubelab-rotation --timeout=120s`, 'Перед сравнением процесс должен реально запуститься.', [['rollout status', 'Ожидать готовность отдельного Deployment.']], 'successfully rolled out.'), S('Измените значение в источнике', `${k} patch secret kubelab-rotation --type merge -p '{"stringData":{"DEMO_TOKEN":"example-generation-two"}}'`, 'Меняем учебное значение в Secret, но не окружение уже работающего процесса.', [['stringData', 'Входное строковое значение, которое сервер сохранит в Secret.']], 'Secret patched.'), S('Проверьте старый процесс', `${k} exec deployment/kubelab-rotation -- node -e "console.log(process.env.DEMO_TOKEN==='example-generation-two')"`, 'Выводим только логический результат; содержимое переменной в журнал не отправляется.', [['===', 'Сравнить полученную строку с ожидаемой учебной версией.']], 'false: прежний процесс ещё использует первоначальное окружение.'), S('Пересоздайте потребителя', `${k} rollout restart deployment/kubelab-rotation`, 'Новые контейнеры получат уже изменённый Secret.', [['rollout restart', 'Изменить шаблон для замены Pod.']], 'Перезапуск запрошен.'), S('Дождитесь новых экземпляров', `${k} rollout status deployment/kubelab-rotation --timeout=120s`, 'Не проверяем новую версию, пока замена ещё не завершена.', [['rollout status', 'Дождаться готовности после замены.']], 'successfully rolled out.'), S('Подтвердите получение новой версии', `${k} exec deployment/kubelab-rotation -- node -e "console.log(process.env.DEMO_TOKEN==='example-generation-two')"`, 'Повторяем то же сравнение в новом процессе.', [['exec deployment/kubelab-rotation', 'Выбрать текущую готовую копию потребителя.']], 'true. Это проверка доставки выдуманной настройки, а не подтверждение отзыва внешнего доступа.'), remove('rotation', 'Удаляем только демонстрационный Secret и потребителя.')],
    recap: ["Обновление Secret и получение нового значения приложением являются разными этапами.","Порядок смены включает проверку новой версии и прекращение использования старой."], exercise: 'Что произойдёт, если отозвать старый пароль до обновления всех потребителей? Оставшиеся процессы начнут получать ошибки; нужен управляемый переход и проверка.', question: 'Что доказывает true в конце опыта?', options: ['Новый процесс получил ожидаемую учебную строку', 'Старый токен отозван во всех внешних системах', 'Все Secret кластера зашифрованы'], answer: 0, answerExplanation: 'Проверка ограничена доставкой конкретной переменной конкретному приложению.' }),
  L({ id: 'metrics', module: 'Наблюдение и масштабирование', title: "Метрики приложения и качество обслуживания", tag: 'Измерения', minutes: 55,
    goal: 'Отличить расход ресурсов от прикладных показателей и прочитать оба источника.',
    introduction: ["Для наблюдения за приложением нужны величины, которые можно сравнивать во времени: число запросов, доля ошибок, длительность и использование ресурсов. Каждая метрика имеет источник, единицу измерения и набор меток. Без этих сведений одинаково выглядящие числа могут описывать совершенно разные процессы.","Получим показатели учебного сервера и разберём различие между накопленным счётчиком и скоростью его изменения. Затем рассмотрим влияние меток на число временных рядов и связь измерений с целями обслуживания. Предупреждение должно опираться на понятное условие и приводить к определённому действию сопровождающего."],
    terms: [['Метрика', 'Измеряемое числовое значение с именем и ограниченным набором признаков.'], ['Счётчик', 'Нарастающее значение, обычно обнуляющееся при перезапуске процесса.'], ['Metrics Server', 'Источник краткосрочных сведений о ресурсах для top и автоматического масштабирования, не долговременная система мониторинга.'], ['Метка метрики', 'Признак ряда, например вид операции. Неконтролируемые значения создают слишком много рядов.']],
    sections: [R("Интерпретация показателей", ['Для ресурса смотрят загрузку, насыщение и ошибки. Для сервиса полезны частота запросов, доля ошибок и задержки. Сопоставляйте показатели с тем, что получает пользователь, и задавайте измеримую цель качества.', 'Среднее время может скрывать редкие очень долгие запросы. Для оценки распределения используют подходящие гистограммы и процентили. Наш небольшой сервер публикует счётчики и суммарное время для учебного чтения; это не полноценная система оценки всех задержек.']), R("Метки и число временных рядов", ['Не добавляйте в метки адрес электронной почты, произвольный URL, идентификатор каждого запроса или токен. В нашем примере учитывается только фиксированный путь /api/runtime. Идентификаторы отдельных запросов подходят для журналов и трассировок с продуманным хранением, но не для неограниченных меток.', 'Каждая копия процесса имеет свои счётчики. Сбор по одному балансируемому адресу Service может попадать в разные копии и создавать ложные скачки. Для полноценного Prometheus настраивают обнаружение и опрос каждого экземпляра, ограниченные права, период опроса и хранение. Grafana показывает сохранённые ряды, но сама не превращает отсутствие данных в измерения.'])],
    steps: [S('Соберите наблюдаемую версию', 'minikube image build -t kubelab:observe . -p kubelab', 'Новый тег не перезаписывает исходную учебную сборку. В текущих файлах сервера есть /metrics и структурированные журналы.', [['-t kubelab:observe', 'Отдельная ссылка на образ для следующих занятий.']], 'Образ собран.'), S('Замените образ приложения', `${k} set image deployment/kubelab web=kubelab:observe`, 'Указываем новый образ конкретному контейнеру web.', [['web=kubelab:observe', 'Имя контейнера слева, ссылка на образ справа.']], 'Шаблон Deployment обновлён.'), S('Дождитесь новой версии', `${k} rollout status deployment/kubelab --timeout=120s`, 'Метрики проверяем у готового нового процесса.', [['rollout status', 'Ожидание замены Pod.']], 'successfully rolled out.'), S('Включите источник ресурсов', 'minikube addons enable metrics-server -p kubelab', 'Это дополнение скачивается при необходимости и использует ресурсы узла.', [['addons enable metrics-server', 'Установить подготовленное Minikube дополнение сбора ресурсов.']], 'Дополнение включено; первые образцы появятся позже.'), S('Дождитесь службы измерений', `${cluster} -n kube-system wait --for=condition=Available deployment/metrics-server --timeout=180s`, 'Сначала проверяем готовность компонента, затем запрашиваем данные.', [['condition=Available', 'Условие доступности Deployment.']], 'condition met. Для первого образца может понадобиться дополнительное время.'), S('Прочитайте расход Pod', `${k} top pods`, 'Это краткосрочный снимок процессора и памяти, не исторический график.', [['top pods', 'Получить сведения о ресурсах через Metrics API.']], 'Таблица CPU и MEMORY. При сообщении о пока отсутствующих метриках подождите и повторите.'), S('Откройте адрес приложения', `${k} port-forward service/kubelab 8081:80`, 'В реальном режиме откройте localhost:8081/api/runtime несколько раз, затем localhost:8081/metrics. После чтения остановите туннель кнопкой «Стоп».', [['8081:80', 'Локальный порт 8081 связан с портом Service 80.']], 'В /metrics видны kubelab_http_requests_total и показатели процесса. В тренажёре настоящий порт не открывается.')],
    recap: ["Метрика рассматривается вместе с её единицей, источником, метками и временем измерения.","Условия предупреждений выбираются с учётом качества обслуживания и возможного действия."], exercise: 'Счётчик уменьшился после обновления. Обязательно ли пропали запросы? Нет: мог смениться или перезапуститься процесс. При анализе нужно учитывать сбросы и идентичность экземпляра.', question: 'Чем Metrics Server отличается от долговременного мониторинга?', options: ['Он не заменяет хранение истории и прикладных показателей', 'Он хранит всю историю запросов', 'Он автоматически создаёт цели качества сервиса'], answer: 0, answerExplanation: 'Снимки ресурсов нужны top и механизмам управления, но не заменяют полный наблюдаемый контур.' }),
  L({ id: 'logging', module: 'Наблюдение и масштабирование', title: "Журналы приложения и поиск событий", tag: 'Сбор и хранение журналов',
    goal: 'Связать запись с экземпляром и запросом, понимая пределы kubectl logs.',
    before: 'Выполните занятие о метриках: приложение должно использовать kubelab:observe. Остановите предыдущий туннель. Записи содержат только фиксированные сведения запроса без его тела, секретных заголовков и параметров адреса.',
    introduction: ["Метрики показывают изменение численных характеристик, а журнал позволяет рассмотреть отдельное событие. При нескольких экземплярах полезно знать, какой процесс записал сообщение, к какому запросу оно относится и каким результатом завершилась операция. Для этого удобны структурированные записи с постоянными именами полей.","Прочитаем журнал учебного приложения и разберём состав записи. Затем рассмотрим доставку, хранение и доступ к журналам после замены Pod. Команда kubectl logs удобна для текущей диагностики, но длительный поиск по нескольким узлам требует отдельного сбора и заранее установленного срока хранения."],
    terms: [['Структурированный журнал', 'Записи с заранее определёнными полями, удобные для поиска и обработки.'], ['Корреляция', 'Связь записей об одной операции через общий идентификатор.'], ['Сборщик журналов', 'Компонент, отправляющий вывод процессов в долговременное хранилище.']],
    sections: [R("Состав записи журнала", ['Нужны время, событие, статус и длительность, а также идентичность экземпляра. В нашем сервере requestId связывает обработку одного обращения. Тело запроса, токены и произвольные заголовки не записываются.', 'Сообщение должно помогать действию: например, назвать безопасный код ошибки и стадию операции. Бесконечное повторение одной большой ошибки затрудняет поиск и увеличивает стоимость хранения. Выбирайте уровень подробности и срок хранения по задаче.']), R("Сбор и хранение журналов", ['Локальный вывод может исчезнуть после удаления Pod или ротации файлов. Команда logs с Deployment обычно выбирает одну копию. Выбор по метке позволяет читать несколько текущих копий, но не превращает kubectl в архив.', 'Для рабочей системы нужен сбор со всех узлов, ограниченный доступ, политика хранения и поиск по общим полям. Время узлов должно быть согласовано. Журналы аудита интерфейса Kubernetes и журналы процесса приложения — разные источники; один не заменяет другой.'])],
    steps: [apply('client', 'Создаём клиента, чтобы запросить приложение из сети кластера.', 'Pod клиента создан.'), S('Создайте проверяемое обращение', `${k} exec pod/kubelab-client -- node -e "fetch('http://kubelab/api/runtime',{headers:{'x-request-id':'kubelab-log-example'},signal:AbortSignal.timeout(3000)}).then(r=>r.json()).then(x=>console.log(x.requestId)).catch(e=>{console.error(e.name);process.exitCode=1})"`, 'Отправляем безопасный учебный идентификатор. Сервер принимает только ограниченный формат значения.', [['x-request-id', 'Идентификатор для связи ответа с записью журнала.']], 'Ответ содержит kubelab-log-example.'), S('Прочитайте записи текущих копий', `${k} logs -l app=kubelab --all-containers=true --prefix=true --tail=20`, 'По метке выбираем копии приложения; префикс помогает определить источник каждой строки.', [['-l app=kubelab', 'Выбрать несколько Pod по метке.'], ['--prefix=true', 'Добавить имя источника.'], ['--tail=20', 'Ограничить количество строк для каждого источника.']], 'В одной из копий найдите JSON-запись с requestId kubelab-log-example. Не все запросы попадают в каждую реплику.'), remove('client', 'Удаляем временного клиента.')],
    recap: ["Структурированные поля позволяют связывать событие с процессом, запросом и результатом.","Текущий журнал контейнера и долговременное хранилище журналов решают разные задачи."], exercise: 'Нужно ли записывать Authorization для облегчения отладки? Нет: используйте безопасный идентификатор, результат и код причины без секрета.', question: 'Почему logs deployment не показывает полную историю всех реплик?', options: ['Обычно выбирается одна копия, а история ограничена доступным выводом', 'Потому что JSON запрещён', 'Потому что Service удаляет журналы'], answer: 0, answerExplanation: 'Для общего архива нужен отдельно настроенный сбор и хранение.' }),
  L({ id: 'tracing', module: 'Наблюдение и масштабирование', title: "Контекст запроса и распределённая трассировка", tag: 'Трассировки и контекст',
    goal: 'Отличить идентификатор запроса от распределённой трассировки и проверить передачу контекста.',
    before: 'Используйте образ kubelab:observe из занятия о метриках. Здесь проверяется чтение контекста и связь с журналом. Сборщик OpenTelemetry и система хранения трассировок в комплект не установлены; реальной цепочки нескольких сервисов наш односервисный пример не создаёт.',
    introduction: ["Один пользовательский запрос может проходить через несколько служб. Журналы каждой из них показывают только локальные события, поэтому для восстановления общего пути требуется передавать сведения о связи между операциями. Распределённая трассировка описывает эту связь с помощью идентификатора трассы и отдельных интервалов работы.","Разберём traceId, spanId и родительскую связь, затем сопоставим контекст HTTP-запроса со строкой журнала. Учебный сервер показывает передачу контекста; для сохранения и просмотра полной трассы необходимы инструментирование, сборщик и хранилище. Их устройство будет рассмотрено в углублённой части."],
    terms: [['Трасса (trace)', 'Связанные участки выполнения одной распределённой операции.'], ['Участок трассы (span)', 'Одна измеряемая операция со временем, контекстом и связью с родителем.'], ['traceparent', 'Стандартный HTTP-заголовок передачи контекста трассировки.'], ['Выборка (sampling)', 'Правило, определяющее, какие трассы сохранять при ограниченных ресурсах.']],
    sections: [R("Связь интервалов одной операции", ['Входящий обработчик принимает контекст или создаёт новый. При обращении к зависимости создаётся дочерний span, а контекст передаётся дальше. Так можно отличить время собственной обработки от ожидания соседнего сервиса.', 'Для полноценной системы нужны библиотеки инструментирования, экспорт, сборщик, хранилище и просмотр. Один и тот же traceId в двух строках журнала помогает корреляции, но сам по себе не создаёт spans, длительности и причинные связи. Именно это ограничение есть у нашей минимальной проверки.']), R("Состав и защита данных наблюдения", ['Не передавайте в атрибутах пароли, содержимое форм или неограниченные пользовательские данные. Продумайте доступ, срок хранения и стоимость выборки. Если выборка отбросила трассу, её отсутствие не доказывает отсутствие запроса.', 'Асинхронная очередь требует осмысленного переноса или связи контекста, а не слепого копирования случайного заголовка. Для каждой стадии определите границу операции, статус ошибки и ответственного за инструментирование. Сопоставляйте трассу с метриками и безопасными журналами по общим идентификаторам.'])],
    steps: [apply('client', 'Создаём отправителя проверяемого запроса.', 'Клиентский Pod создан.'), S('Передайте известный контекст', `${k} exec pod/kubelab-client -- node -e "fetch('http://kubelab/api/runtime',{headers:{traceparent:'00-0123456789abcdef0123456789abcdef-0123456789abcdef-01'},signal:AbortSignal.timeout(3000)}).then(r=>r.json()).then(x=>console.log(x.traceId)).catch(e=>{console.error(e.name);process.exitCode=1})"`, '32 шестнадцатеричных символа в середине заголовка — идентификатор трассы. В примере используются только выдуманные данные.', [['traceparent', 'Версия, trace-id, parent-id и флаги в стандартном формате.']], '0123456789abcdef0123456789abcdef. Это подтверждает чтение контекста нашим сервером.'), S('Найдите контекст в журнале', `${k} logs -l app=kubelab --all-containers=true --prefix=true --tail=20`, 'Сверьте traceId с ответом. Запись будет у обслужившей запрос копии.', [['--prefix=true', 'Помочь найти конкретный Pod-источник.']], 'В одной JSON-записи есть тот же traceId.'), remove('client', 'Завершаем минимальную проверку контекста.')],
    recap: ["Операции разных служб связываются общим traceId и отношениями между span.","Передача контекста является частью трассировки, но не заменяет сбор и хранение интервалов."], exercise: 'Нарисуйте путь «шлюз → сервис → база». Укажите три spans, их родительские связи, место экспорта и способ поиска журнала по traceId. Это схема будущего наблюдения, а не уже установленная система.', question: 'Достаточно ли одного поля traceId для полной трассировки?', options: ['Нет, нужны измеряемые spans, передача и сбор данных', 'Да, больше компонентов не нужно', 'Да, если идентификатор длинный'], answer: 0, answerExplanation: 'Корреляция является частью решения, но не заменяет данные о выполнении операций.' })
);

const sequence = ['architecture','deployment-models','runtime','api-identity','lifecycle','scheduling','batch','stateful','storage-operations','dns','cni','ingress','network-policy','tenants','pod-security','secret-rotation','metrics','logging','tracing','autoscaling','cluster-maintenance','helm','kustomize','delivery','rollout-strategies','operators','platform'];
advancedLessons.sort((a,b) => sequence.indexOf(a.id)-sequence.indexOf(b.id));
for (const [id, practiceKind] of Object.entries({ 'deployment-models': 'Разбор и расчёт', 'storage-operations': 'План восстановления', cni: 'Исследование сети', tracing: 'Проверка контекста', 'cluster-maintenance': 'План обслуживания', platform: 'Итоговый проект' })) advancedLessons.find(lesson => lesson.id === id).practiceKind = practiceKind;
const extend = (id, section) => advancedLessons.find(lesson => lesson.id === id).sections.push(section);
extend('deployment-models', R('Пулы узлов и несколько кластеров', ['Разным приложениям могут понадобиться разные узлы: например, с ускорителями, большим объёмом памяти или отдельными условиями доступа. Пул узлов — управляемая группа с общими свойствами. Запрос к такому пулу нужно выразить поддерживаемыми правилами размещения, а его обслуживание и ёмкость учитывать отдельно.', 'Несколько кластеров дают дополнительные границы отказа и управления, но усложняют доставку, идентичность, сеть и данные. Федерация или общая система управления не превращает независимые etcd в одно хранилище. Для каждого кластера нужны свои доступ, наблюдение и восстановление.', 'Выбирайте уровни «разработка, проверка, рабочая среда» по требованиям риска и ответственности. Не используйте только название Namespace как доказательство полной изоляции от администратора общего кластера.']));
extend('cni', R("Адресация, маршрутизация и MTU", ['Кто-то должен выдать Pod уникальный адрес из согласованного пула и освободить его после удаления. Если диапазоны Pod, Service и основной сети конфликтуют, запрос может уходить не туда даже при правильном приложении. План адресов проверяют до развёртывания.', 'Для связи между узлами можно распространять маршруты к сетям Pod, например с помощью протокола обмена маршрутами, либо передавать пакеты через наложенную сеть. Это меняет требования к маршрутизаторам и допустимому размеру пакета. При инкапсуляции часть размера занимает внешний заголовок; неправильный максимальный размер пакета может давать ошибки только на больших ответах.', 'Балансировка транспортного уровня работает с соединениями, а HTTP-прокси может выбирать маршрут по имени, пути и другим признакам протокола. Сервисная сеть с прокси добавляет свои правила маршрутизации, наблюдение и взаимную проверку личности. Её нельзя считать обязательной частью любого Kubernetes: внедрение оправдывают конкретной задачей и измеряют его накладные расходы.']));
extend('storage-operations', R("Файловое, блочное и объектное хранение", ['Блочный том предоставляет устройство, на котором может находиться файловая система. Файловое хранилище предоставляет готовый доступ к файлам по своему протоколу. Объектное хранилище обычно доступно через отдельный интерфейс и не становится полноценной файловой системой только из-за похожего имени каталога.', 'Режимы доступа описывают поддерживаемый способ подключения, а не протокол безопасной записи приложения. ReadWriteOnce означает один узел, ReadWriteMany — возможность работы с нескольких узлов при поддержке хранилища. Ни один такой флаг не исправляет приложение, не рассчитанное на нескольких писателей.', 'У CSI есть компоненты управления и компоненты на узлах. Контроллер организует выделение и подключение в пределах возможностей поставщика, а узловая часть готовит доступ для Pod. Установка только описания StorageClass не устанавливает драйвер. Для снимков нужны и совместимый драйвер, и дополнительные обслуживающие компоненты.']));
extend('api-identity', R("Внешняя аутентификация и допуск", ['В организациях часто подключают внешний поставщик идентичности и выдают роли группам. Нужно точно определить, как удостоверяется пользователь, какие группы приходят в запрос и как быстро отзывается доступ после изменения группы. ServiceAccount приложения и человек с внешней учётной записью имеют разные жизненные циклы.', 'Внешний обработчик допуска становится зависимостью сервера управления. Таймауты, проверка его сертификата и поведение при недоступности нужно выбирать осознанно. Разрешать всё при отказе может нарушить защиту, а запрещать всё — остановить новые развёртывания. Нужны наблюдение, ограниченная область действия и восстановимая процедура изменения.', 'Изменяющий обработчик может дописать значения, а проверяющий — отвергнуть результат. Контролируйте совместимость нескольких правил и не заставляйте один обработчик бесконечно отменять изменения другого. Секреты и полные тела запросов нельзя без разбора отправлять в журналы такого компонента.']));
extend('metrics', R("Цели качества и оповещения", ['Для пользовательского сервиса начните с задержки, частоты запросов, ошибок и насыщения. Для отдельного ресурса полезно оценивать использование, очередь ожидания и ошибки. Эти группы вопросов дополняют друг друга: занятый процессор не всегда неисправность, а низкая загрузка не всегда здоровье.', 'Сформулируйте показатель качества и период: например, доля успешных запросов за согласованное время. Затем определите допустимое отклонение и действие дежурного. Предупреждение без понятной реакции часто становится шумом.', 'Панель должна показывать единицы, окно расчёта и отсутствие данных. Не рисуйте отсутствие измерений как нулевые ошибки. Для полноценного мониторинга отдельно настраиваются сбор, долговременное хранение, панели, уведомления и проверка самого контура наблюдения.']));
extend('delivery', R("Базовый образ и зависимости", ['Выбирайте основу по необходимым библиотекам, сроку поддержки, пользователю процесса и способу обновления. Большой универсальный «золотой образ» усложняет учёт ненужных компонентов и связывает независимые приложения. Малый образ тоже требует проверки совместимости и обновления.', 'Закрепляйте версии зависимостей и сохраняйте сведения о составе результата. Разделение сборочного и рабочего окружений позволяет не переносить компиляторы и секреты сборки в исполняемый образ. Подготовка через buildpacks — другой вариант автоматизации, который всё равно должен давать проверяемый и обновляемый результат.', 'При обнаружении проблемы важно уметь запретить дальнейшую доставку конкретного результата, определить уже использующие его окружения и подготовить замену. Карантин и проверка подписи работают только при настроенных правилах доверия. Проверяйте сам механизм отказа на отдельном учебном результате.']));
for (const lesson of advancedLessons) {
  const index = lesson.steps.findIndex(step => step.command.endsWith(' apply -f k8s/advanced/client.yaml'));
  if (index >= 0) lesson.steps.splice(index + 1, 0, S('Дождитесь клиентского Pod', `kubectl --context ${lesson.context} -n kubelab wait --for=condition=Ready pod/kubelab-client --timeout=120s`, 'Не запускаем программу в ещё не подготовленном контейнере.', [['condition=Ready', 'Ожидать готовности выбранного Pod.']], 'condition met. При ошибке ожидания проверьте образ и события перед запросом.'));
}
